import from "@/assets/images/icons" { IconCaretDown }
import from "@/components/ui" { Icon }
import from "@/lib/tailwind/utils" { cn }
import from "@radix-ui/react-select" { Icon as PrimitiveIcon, Trigger as PrimitiveTrigger }

glob defaultIconProps: dict[str, object] = {"size": 2.5, "color": "gray-dark"};

def selectTriggerClassName(variant: str | None, h: str | None, className: str | None) -> str {
    base = "flex items-center justify-between w-full text-base focus:outline-none disabled:cursor-not-allowed data-[placeholder]:text-gray data-[placeholder]:select-none";
    v = variant if variant is not None else "rounded";
    hVal = h if h is not None else "md";
    variantCls = "";
    if v == "rounded" {
        variantCls = cn(
            "rounded-full bg-white border border-gray pl-6 pr-4 py-4",
            "focus:ring-2 focus:ring-primary-dark focus:border-transparent",
            "data-[state=open]:ring-2 data-[state=open]:ring-primary-dark data-[state=open]:border-transparent",
        );
    }
    heightCls = "h-12" if hVal == "md" else "";
    return cn(base, variantCls, heightCls, className);
}

def:pub SelectTrigger(className: str | None = None, children: object | None = None, variant: str | None = None, h: str | None = None, iconProps: dict[str, object] | None = None, ref: Ref[object] = Ref()) -> JsxElement {
    resolvedIconProps = iconProps if iconProps is not None else defaultIconProps;
    return <PrimitiveTrigger className={selectTriggerClassName(variant, h, className)} ref={ref}>
        {children}
        <PrimitiveIcon asChild={True}>
            <Icon icon={IconCaretDown} {**resolvedIconProps} />
        </PrimitiveIcon>
    </PrimitiveTrigger>;
}

