import from "react" { useId }
import from "@/lib/utils" { cn }

def SpinningText(
    text: str,
    radius: int = 37,
    textClassName: str = "text-[8px]",
    speed: int = 10,
    direction: str = "normal",
    className: str = ""
) -> JsxElement {
    path_id = useId();
    path_d = f"M 50,50 m -{radius},0 a {radius},{radius} 0 1,1 {radius * 2},0 a {radius},{radius} 0 1,1 -{radius * 2},0";

    <div className={className}>
        <svg viewBox="0 0 100 100" className="w-full h-full">
            <g
                className="origin-center animate-spin"
                style={{"animationDuration": f"{speed}s", "animationDirection": direction}}
