                <path id={path_id} d={path_d} fill="none" />
                <text className={cn("uppercase font-normal fill-muted-foreground tracking-widest", textClassName)}>
                    <textPath href={f"#{path_id}"} startOffset="0%">
                        {text}
                    </textPath>
                </text>
            </g>
        </svg>
    </div>
}

