def:pub TokenUsageDemo(
    title: str = "Token Usage This Month",
    upgradeLabel: str = "Upgrade",
    usageSummary: str = "1.2M / 2M tokens",
    usagePercent: int = 60,
    usagePercentLabel: str = "60% used",
    breakdown: list[TokenBreakdownItem] = defaultBreakdown,
) -> JsxElement {
    has isOpen: bool = False;

    <div className="w-full max-w-xs">
        <Collapsible open={isOpen} onOpenChange={lambda (value: bool) { isOpen = value; }} className="relative">
            <Card>
                <CardHeader className="flex items-center justify-between">
                    <CardTitle className="text-sm">
                        title;
                    </CardTitle>
                    <CardAction>
                        <Button variant="outline" size="xs" className="cursor-pointer">
                            upgradeLabel;
                        </Button>
                    </CardAction>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="bg-muted dark:bg-muted/50 border-border rounded-lg space-y-2 border p-3">
                        <div className="flex justify-between text-sm font-medium">
                            <span>
                                usageSummary;
                            </span>
                            <span>
                                usagePercentLabel;
                            </span>
                        </div>
                        <Progress
                            value={usagePercent}
                            className="**:data-[slot=progress-track]:bg-primary/20 **:data-[slot=progress-track]:h-1.5"
                        />
                    </div>
                    <motion.div
                        initial="closed"
                        animate={"open" if isOpen else "closed"}
                        variants={contentVariants}
                        style={{"overflow": "hidden"}}
                    >
                        <div className="flex flex-col gap-2.5 pt-2">
                            {for item in breakdown {
                                <div key={item.label} className="flex justify-between text-xs">
                                    <span className="text-muted-foreground font-medium">
                                        item.label;
                                    </span>
                                    <span className="font-medium text-foreground">
                                        item.value;
                                    </span>
                                </div>
                            }}
                        </div>
                    </motion.div>
                </CardContent>
            </Card>
            <div className="absolute -bottom-3 left-1/2 -translate-x-1/2">
                <CollapsibleTrigger asChild={True}>
                    <Button variant="outline" size="icon" className="size-6 rounded-full shadow-sm cursor-pointer">
                        <motion.span
                            animate={{"rotate": 180 if isOpen else 0}}
                            transition={{"duration": 0.25, "ease": "easeInOut"}}
                            className="inline-flex"
                        >
                            <ChevronDownIcon aria-hidden="true" className="size-3.5" />
                        </motion.span>
                    </Button>
                </CollapsibleTrigger>
            </div>
        </Collapsible>
    </div>
}

