    allDefinitions = await db.query.definitions.findMany({"where": eq(definitions.status, "approved"), "columns": {"term": true}});
    return [{"url": f"{env.NEXT_PUBLIC_BASE_URL}/define/{termToSlug(defn["term"])}", "lastModified": new(Date, []), "changeFrequency": "daily", "priority": 0.7} for defn in allDefinitions];
