# from: thangdevalone__modern-ui::hooks/use-click-away.js
import from "react" { useEffect }

obj RefObject[T] {
    has current: T | None = None;
}

obj DOMElement {
    def contains(other: object) -> bool;
}

def:pub useClickAway(ref: RefObject[DOMElement], handler: Callable[[Event], None]) {
    useEffect(lambda {
        listener = lambda (event: Event) {
            if not ref.current or ref.current.contains(event.target as object) {
                return;
            }
            handler(event);
        };
        document.addEventListener("mousedown", listener);
        document.addEventListener("touchstart", listener);
        return lambda {
            document.removeEventListener("mousedown", listener);
            document.removeEventListener("touchstart", listener);
        };
    }, [ref, handler]);
}

