# Language: Jac
# from: beyondlong__resume-builder::helpers/storage.ts
glob STORAGE_KEY = "resume-config";

def:pub saveToStorage(config: dict[str, object]) {
    if localStorage {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
    }
}

def:pub loadFromStorage() -> dict[str, object] | None {
    if not localStorage {
        return None;
    }
    try {
        data = localStorage.getItem(STORAGE_KEY);
        return JSON.parse(data) as dict[str, object] if data else None;
    } except Exception {
        return None;
    }
}

def:pub clearStorage() {
    if localStorage {
        localStorage.removeItem(STORAGE_KEY);
    }
}

