def:pub EnvironmentButtonGroup() -> JsxElement {
    has active: str = "development";

    def set_active(envId: str) {
        active = envId;
    }

    <ButtonGroup>
        {for env in environments {
            isActive = active == env.id;
            borderRadiusClass = "";
            if env.id == "development" {
                borderRadiusClass = "rounded-l-lg! rounded-r-none!";
            } elif env.id == "staging" {
                borderRadiusClass = "rounded-none!";
            } elif env.id == "production" {
                borderRadiusClass = "rounded-l-none! rounded-r-none!" if active == "production" else "rounded-l-none! rounded-r-lg!";
            }
            <Button
                key={env.id}
                variant="outline"
                className={cn(
                    "relative overflow-hidden transition-colors duration-300 cursor-pointer",
                    borderRadiusClass,
                    "text-primary-foreground hover:text-primary-foreground border-transparent"
                        if isActive
                        else "text-muted-foreground hover:text-foreground",
                )}
                onClick={lambda { set_active(env.id); }}
            >
                {if isActive {
                    <motion.span
                        layoutId="active-env-bg"
                        className="absolute inset-0 bg-primary"
                        transition={{"type": "spring", "stiffness": 350, "damping": 28}}
