                    <motion.span
                        animate={"active" if isActive else "inactive"}
                        whileHover="hover"
                        variants={env.variants}
                    >
                        {render_env_icon(env.id)}
                    </motion.span>
                    <span>{env.label}</span>
                </span>
            </Button>
