def:pub getNextHighlightIndex(currentIndex: float, direction: str, total: float) -> float {
    if (total <= 0) {
        return -1;
    }
    if (currentIndex < 0) {
        return (0 if (direction == "next") else (total - 1));
    }
    if (direction == "next") {
        return ((currentIndex + 1) % total);
    }
    return (((currentIndex - 1) + total) % total);
}

