glob:pub SUPPORTED_LANGS = ["es", "en"];

glob:pub DEFAULT_LANG: str = "es";

def:pub getLangFromPath(pathname: str) -> str {
    first = pathname.split("/")[1];
    return ("en" if (first == "en") else DEFAULT_LANG);
}

def:pub isLang(value: str) -> bool {
    return (value in SUPPORTED_LANGS);
}

def:pub stripAppBase(pathname: str, appBase: str) -> str {
    if (appBase and pathname.startswith(appBase)) {
        rest = pathname[len(appBase):];
        return ("/" if (rest == "") else rest);
    }
    return pathname;
}

def:pub baseForLang(lang: str) -> str {
    return ("/en" if (lang == "en") else "");
}

def:pub stripLangPrefix(pathname: str) -> str {
    if (pathname == "/en") {
        return "/";
    }
    if pathname.startswith("/en/") {
        return pathname[3:];
    }
    return pathname;
}

def:pub withLang(pathname: str, lang: str) -> str {
    bare = stripLangPrefix(pathname);
    if (lang == "es") {
        return bare;
    }
    return ("/en" if (bare == "/") else f"/en{bare}");
}

