import re;
import from "lucide-react" { CheckCircle2, EyeClosed, X, Eye }
import from "@/components/ui/input" { Input }
import from "@/components/ui/label" { Label }
import from "@/components/ui/button" { Button }
import from "@/lib/utils" { cn }

glob title: str = "Password Validation";

obj ValidationRule {
    has text: str;
    has valid: bool;
}

def get_strength_color(score: int) -> str {
    if score == 0 { return "bg-muted"; }
    if score <= 1 { return "bg-red-500"; }
    if score <= 2 { return "bg-orange-500"; }
    if score <= 3 { return "bg-teal-400"; }
    return "bg-teal-500";
}

def get_strength_text(score: int) -> str {
    if score == 0 { return ""; }
    if score <= 1 { return "Weak"; }
    if score <= 2 { return "Moderate"; }
    if score <= 3 { return "Strong"; }
    return "Very Strong";
}

def get_strength_text_color(score: int) -> str {
    if score == 0 { return "text-muted-foreground"; }
    if score <= 1 { return "text-red-500"; }
    if score <= 2 { return "text-orange-500"; }
    if score <= 3 { return "text-teal-400"; }
    return "text-teal-500";
}

def:pub InputRealTimeValidationDemo() -> JsxElement {
    has password: str = "";
    has showPassword: bool = False;

    validations: list[ValidationRule] = [
        ValidationRule(text="At least 8 characters", valid=len(password) >= 8),
        ValidationRule(text="Contains a number", valid=bool(re.search(r"\d", password))),
        ValidationRule(text="Contains uppercase letter", valid=bool(re.search(r"[A-Z]", password))),
        ValidationRule(text="Contains special character", valid=bool(re.search(r"[!@#$%^&*]", password))),
    ];
    strength: int = len([v for v in validations if v.valid]);

    def handle_password_change(e: ChangeEvent) {
        password = e.target.value;
    }

    def toggle_show_password(_: MouseEvent) {
        showPassword = not showPassword;
    }

    <div className="w-full max-w-sm space-y-4">
        <div className="space-y-2">
            <Label htmlFor="password-realtime">Password</Label>
            <div className="relative">
                <Input
                    className="bg-transparent"
                    id="password-realtime"
                    onChange={handle_password_change}
                    placeholder="Enter password"
                    type={"text" if showPassword else "password"}
                    value={password}
                />
                <Button
                    className="absolute top-0 right-0 h-full px-3 hover:bg-transparent"
                    onClick={toggle_show_password}
                    size="icon"
                    type="button"
                    variant="ghost"
                >
                    {if showPassword {
                        <Eye className="h-4 w-4 text-muted-foreground" />;
                    } else {
                        <EyeClosed className="h-4 w-4 text-muted-foreground" />;
                    }}
                </Button>
            </div>
        </div>
        <div className="space-y-2">
            <div className="h-1 w-full overflow-hidden rounded-full bg-secondary">
                <div
                    className={cn("h-full transition-all duration-500 ease-out", get_strength_color(strength))}
                    style={{"width": f"{(strength / 4) * 100}%"}}
                />
            </div>
            <div className="flex items-center justify-between text-xs font-medium">
                <span className="text-muted-foreground">Password must contain</span>
                <span className={get_strength_text_color(strength)}>{get_strength_text(strength)}</span>
            </div>
        </div>
        <div className="space-y-1.5 pt-1">
            {for validation in validations {
                <div
                    key={validation.text}
                    className={cn(
                        "flex items-center gap-2 text-sm transition-colors duration-200",
                        "text-teal-400 dark:text-teal-400" if validation.valid else "text-muted-foreground"
                    )}
                >
                    {if validation.valid {
                        <CheckCircle2 className="h-4 w-4" />;
                    } else {
                        <X className="h-4 w-4" />;
                    }}
                    {validation.text}
                </div>
            }}
        </div>
    </div>
}

