# from: shadcnspace__shadcnspace::app/api/registry/route.ts
import json;
import os;
import from config.registry.blocks { blocks, RegistryBlock }
import from config.registry.components { components }

def _to_registry_item(item: RegistryBlock) -> dict[str, object] {
    dependencies = item.dependencies if item.dependencies else [];
    registryDependencies = item.registryDependencies if item.registryDependencies else [];
    files = item.files if item.files else [];
    return {
        "name": item.name,
        "title": item.title,
        "description": item.description,
        "type": item.type,
        "dependencies": dependencies,
        "registryDependencies": registryDependencies,
        "files": files,
    };
}

glob blockItems: list[dict[str, object]] = [_to_registry_item(b) for b in blocks];
glob componentItems: list[dict[str, object]] = [_to_registry_item(c) for c in components];

async def:pub GET() -> dict[str, object] {
    schema = "https://ui.shadcn.com/schema/registry.json";
    homepage = "https://shadcnspace.com";
    registry = {
        "$schema": schema,
        "name": "Shadcn Space",
        "homepage": homepage,
        "items": blockItems + componentItems,
    };
    outputPath = os.path.abspath("./registry.json");
    with open(outputPath, "w") as fh {
        fh.write(json.dumps(registry, indent=2));
    }
    return {"message": "Registry generated successfully"};
}

