import re;

import from "lucide-react" { Wifi }
import from "@/components/ui/input" { Input }
import from "@/components/ui/label" { Label }

def format_mac(value: str) -> str {
    hex_chars = re.sub(r"[^0-9a-fA-F]", "", value)[:12].upper();
    groups = re.findall(r".{1,2}", hex_chars);
    return ":".join(groups) if groups else hex_chars;
}

