# from: badsyntax__mailinabox-ui::auth/StorageAuth.ts
glob:pub STORAGE_KEY = "miab-cp-credentials";

glob:pub CREDENTIALS_SEPERATOR = ":";

def buildStorageCredentials(username: str, password: str) -> str {
    return f"{username}{CREDENTIALS_SEPERATOR}{password}";
}

class:pub StorageAuth {
    has username: str = "";
    has password: str = "";
    has isAuthenticated: bool = False;

    def init(credentials: str) {
        parts = credentials.split(CREDENTIALS_SEPERATOR);
        self.username = parts[0] if len(parts) > 0 else "";
        self.password = parts[1] if len(parts) > 1 else "";
        self.isAuthenticated = bool(self.username and self.password);
    }

    def getUsername() -> str {
        return self.username;
    }

    def getPassword() -> str {
        return self.password;
    }

    def setUsername(username: str) {
        self.username = username;
    }

    def setPassword(password: str) {
        self.password = password;
    }

    def getIsAuthenticated() -> bool {
        return self.isAuthenticated;
    }

    def persistToStorage(remember: bool) {
        credentials = buildStorageCredentials(self.username, self.password);
        if remember {
            localStorage.setItem(STORAGE_KEY, credentials);
            sessionStorage.removeItem(STORAGE_KEY);
        } else {
            localStorage.removeItem(STORAGE_KEY);
            sessionStorage.setItem(STORAGE_KEY, credentials);
        }
    }

    def clear() {
        localStorage.removeItem(STORAGE_KEY);
        sessionStorage.removeItem(STORAGE_KEY);
    }
}

