def LinkPopover(editor: Editor) -> JsxElement {
    has open: bool = False;
    has url: str = "";
    def handle_open_change(nextOpen: bool) {
        open = nextOpen;
    }
    def handle_url_change(e: ChangeEvent) {
        url = e.target.value;
    }
    def apply_link() {
        if url {
            editor.chain().focus().extendMarkRange("link").setLink({"href": url}).run();
        } else {
            editor.chain().focus().extendMarkRange("link").unsetLink().run();
        }
        open = False;
    }
    return <Popover open={open} onOpenChange={handle_open_change}><PopoverTrigger asChild><Button size="sm" variant="ghost" className="h-8 w-8 p-0"><LinkIcon className="h-4 w-4" /></Button></PopoverTrigger><PopoverContent className="w-80 p-2"><div className="flex items-center gap-2"><Input value={url} onChange={handle_url_change} placeholder="https://" /><Button size="sm" onClick={apply_link} children={<Check className="h-4 w-4" />} /></div></PopoverContent></Popover>;
}

