import from "jsonwebtoken" { default as jwt }
import os;

glob JWT_SECRET: str = os.environ.get("SESSION_SECRET", "");
glob JWT_ALGORITHM: str = "HS256";
glob JWT_EXPIRY: str = "24h";

def:pub signToken(payload: dict[str, str]) -> str {
    return jwt.sign(payload, JWT_SECRET, {"algorithm": JWT_ALGORITHM, "expiresIn": JWT_EXPIRY});
}

def:pub verifyToken(token: str) -> dict[str, str] | None {
    try {
        return jwt.verify(token, JWT_SECRET, {"algorithms": [JWT_ALGORITHM]}) as dict[str, str];
    } except Exception {
        return None;
    }
}

