import from "dayjs" { Dayjs }

def startOfWeek(date: Dayjs, weekStartsOn: int) -> Dayjs {
    diff = ((date.day() - weekStartsOn) + 7) % 7;
    return date.subtract(diff, "day").startOf("day");
}

def:pub isSameWeek(a: Dayjs, b: Dayjs, weekStartsOn: int) -> bool {
    return startOfWeek(a, weekStartsOn).isSame(startOfWeek(b, weekStartsOn), "day");
}

