import from "motion/react" { motion, AnimatePresence }
import from "lucide-react" { Send, Loader2, Check }
import from "@/lib/utils" { cn }

def:pub MultiStateSendButton(
    idleLabel: str = "Send Message",
    loadingLabel: str = "Sending...",
    successLabel: str = "Sent Successfully!",
    sendDuration: int = 1800,
    autoResetDelay: int = 3000,
    onSend: Callable[[], None] | None = None,
    className: str = "",
    onClick: Callable[[MouseEvent], None] | None = None,
    disabled: bool = False,
    props: dict[str, object] = {},
    ref: Ref[HTMLButtonElement] = Ref(),
) -> JsxElement {
    has status: str = "idle";

    def handle_click(e: MouseEvent) {
        if status != "idle" { return; }
        status = "loading";
        setTimeout(lambda {
            status = "success";
            if onSend { onSend(); }
            if autoResetDelay > 0 {
                setTimeout(lambda { status = "idle"; }, autoResetDelay);
            }
        }, sendDuration);
        if onClick { onClick(e); }
    }

    <motion.button
        ref={ref}
        onClick={handle_click}
        disabled={disabled or status != "idle"}
        whileHover={{"scale": 1.02 if status == "idle" else 1}}
        whileTap={{"scale": 0.97 if status == "idle" else 1}}
        className={cn(
            "group relative inline-flex items-center justify-center gap-2.5 overflow-hidden rounded-xl px-6 py-3 font-medium text-sm transition-all duration-300 select-none outline-none min-w-44 border",
            "bg-background text-foreground border-border hover:text-primary hover:bg-muted dark:hover:bg-input/50 cursor-pointer" if status == "idle" else "bg-primary text-primary-foreground border-primary cursor-not-allowed!" if status == "success" else "bg-background text-foreground border-border cursor-not-allowed!",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
            "disabled:cursor-not-allowed!",
            disabled and "opacity-60",
            className,
        )}
        {**props}
    >
        <AnimatePresence mode="wait" initial={False}>
            {if status == "idle" {
                <motion.span
                    key="idle"
                    initial={{"opacity": 0, "y": 10}}
                    animate={{"opacity": 1, "y": 0}}
                    exit={{"opacity": 0, "y": -10}}
                    transition={{"duration": 0.2}}
                    className="relative z-10 flex items-center gap-2 font-medium"
                >
                    <Send className="size-4 text-foreground transition-all group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                    <span>{idleLabel}</span>
                </motion.span>
            }}
            {if status == "loading" {
                <motion.span
                    key="loading"
                    initial={{"opacity": 0, "y": 10}}
                    animate={{"opacity": 1, "y": 0}}
                    exit={{"opacity": 0, "y": -10}}
                    transition={{"duration": 0.2}}
                    className="relative z-10 flex items-center gap-2 font-medium text-primary"
                >
                    <Loader2 className="size-4 animate-spin" />
                    <span>{loadingLabel}</span>
                </motion.span>
            }}
            {if status == "success" {
                <motion.span
                    key="success"
                    initial={{"opacity": 0, "y": 10}}
                    animate={{"opacity": 1, "y": 0}}
                    exit={{"opacity": 0, "y": -10}}
                    transition={{"duration": 0.2}}
                    className="relative z-10 flex items-center gap-2 font-medium text-primary-foreground"
                >
                    <Check className="size-4" />
                    <span>{successLabel}</span>
                </motion.span>
            }}
        </AnimatePresence>
    </motion.button>
}

