def:pub Pagination(
    onPrevious: Callable[[], None],
    onNext: Callable[[], None],
    previousDisabled: bool,
    nextDisabled: bool,
    visible: bool,
    page: int,
) -> JsxElement {
    <div className="mt-2" style={{"display": "block" if visible else "none"}}>
        <button
            className={f"{('bg-gray-300 cursor-not-allowed' if previousDisabled else 'bg-blue-500')} rounded p-1 text-white font-bold mr-2"}
            onClick={onPrevious}
            disabled={previousDisabled}
        >
            ←
        </button>
        <span className="bg-gray-300 p-2 rounded">{page}</span>
        <button
            className={f"{('bg-gray-300 cursor-not-allowed' if nextDisabled else 'bg-blue-500')} rounded p-1 text-white font-bold ml-2"}
            onClick={onNext}
            disabled={nextDisabled}
        >
            →
        </button>
    </div>
}

