import from "next/navigation" { useSearchParams }
import from "@/features/subscriptions/store/use-cancel-modal" { useCancelModal }
import from "@/features/subscriptions/store/use-success-modal" { useSuccessModal }

def:pub SubscriptionAlert() -> None {
    params = useSearchParams();
    cancelModal = useCancelModal();
    onOpenCancel = cancelModal.onOpen;
    successModal = useSuccessModal();
    onOpenSuccess = successModal.onOpen;
    canceled = params.get("canceled");
    success = params.get("success");
    can with [canceled] entry {
        if canceled {
            onOpenCancel();
        }
    }
    can with [success] entry {
        if success {
            onOpenSuccess();
        }
    }
    return None;
}

