import from "@/components/date-range-picker" { DateRangePicker }
import from "@/components/layout/shell" { Shell }
import from "@/components/pages/dashboard/dashboard-cards" { DashboardCards }
import from "@/components/pages/dashboard/dashboard-header" { DashboardHeader }

glob:pub metadata: dict[str, str] = {"title": "Dashboard", "description": "Monitor your progress."};

async def:pub Dashboard(searchParams: dict[str, str]) -> JsxElement {
    user = await getCurrentUser();
    if not user {
        redirect((authOptions or {}).get("pages", {}).get("signIn") or "/signin");
    }
    dateRange = dateRangeParams(searchParams);
    dashboardData = await getDashboardData(user.id, dateRange);
    activityData = len(dashboardData.activityCountByDate) > 0 and len(dashboardData.topActivities) > 0;
    layout = "grid grid-cols-1 gap-4 md:grid-cols-2" if activityData else "grid grid-cols-1";
    scrollClass = "h-[17rem] rounded-lg border" if activityData else "h-[25.1rem] rounded-lg border";
    return <Shell>
        <DashboardHeader heading="Dashboard" text="Monitor your progress.">
            <DateRangePicker />
        </DashboardHeader>
        <div className={layout}>
            <ScrollArea className={scrollClass}>
                <div className="divide-y divide-border">
                    <ActivityList activities={dashboardData.userActivities} />
                </div>
            </ScrollArea>
            {activityData and <>
                <DashboardCards data={dashboardData} searchParams={searchParams} />
                <LineChartComponent data={dashboardData.activityCountByDate} />
                <PieChartComponent data={dashboardData.topActivities} />
            </>}
        </div>
        <DataTable columns={logColumns} data={dashboardData.logs}>Log History</DataTable>
    </Shell>;
}

