import from "@/lib/supabase/admin" { supabaseAdmin }
import from "@/lib/retention-days" { RETENTION_DAYS }

async def:pub deleteSessionStorageFolder(bucket: str, sessionId: str) -> int {
    listResponse = await supabaseAdmin.storage.from(bucket).list(sessionId, {"limit": 1000});
    files = listResponse.data;
    if not files or len(files) == 0 {
        return 0;
    }
    paths = [f"{sessionId}/{fileEntry['name']}" for fileEntry in files];
    removeResponse = await supabaseAdmin.storage.from(bucket).remove(paths);
    if removeResponse.error {
        return 0;
    }
    return len(paths);
}

async def:pub deleteSessionSegmentFiles(sessionId: str) -> int {
    listResponse = await supabaseAdmin.storage.from("recordings").list(sessionId, {"limit": 100});
    files = listResponse.data;
    if not files {
        return 0;
    }
    segFiles = [f"{sessionId}/{fileEntry['name']}" for fileEntry in files if "-seg" in fileEntry["name"]];
    if len(segFiles) == 0 {
        return 0;
    }
    removeResponse = await supabaseAdmin.storage.from("recordings").remove(segFiles);
    if removeResponse.error {
        return 0;
    }
    return len(segFiles);
}

