import from "lucide-react" { CreditCardIcon, SettingsIcon, UserIcon }
import from "@/components/ui/button" { Button }
import from "@/components/ui/command" {
    Command,
    CommandDialog,
    CommandEmpty,
    CommandGroup,
    CommandInput,
    CommandItem,
    CommandList,
    CommandShortcut,
}

obj CommandMenuItem {
    has label: str;
    has icon_name: str | None = None;
    has shortcut: str | None = None;
    has on_select: Callable[[], None] | None = None;
}

obj CommandMenuGroup {
    has heading: str;
    has items: list[CommandMenuItem];
}

glob default_groups: list[CommandMenuGroup] = [
    CommandMenuGroup(
        heading="Settings",
        items=[
            CommandMenuItem(label="Profile", icon_name="user", shortcut="⌘P"),
            CommandMenuItem(label="Billing", icon_name="credit-card", shortcut="⌘B"),
            CommandMenuItem(label="Settings", icon_name="settings", shortcut="⌘S"),
        ],
    ),
];

def shortcut_menu_icon(name: str | None) -> JsxElement | None {
    if name == "user" {
        return <UserIcon />;
    }
    if name == "credit-card" {
        return <CreditCardIcon />;
    }
    if name == "settings" {
        return <SettingsIcon />;
    }
    return None;
}

def:pub CommandShortcutDemo(
    button_label: str = "Shortcut Menu",
    placeholder: str = "Type a command or search...",
    empty_message: str = "No results found.",
    groups: list[CommandMenuGroup] = default_groups,
) -> JsxElement {
    has open: bool = False;

    def handle_open_change(next_open: bool) {
        open = next_open;
    }

    def open_dialog(e: MouseEvent) {
        open = True;
    }

    <div className="flex flex-col gap-4">
        <Button onClick={open_dialog} variant="outline" className="w-fit cursor-pointer">
            {button_label}
        </Button>
        <CommandDialog open={open} onOpenChange={handle_open_change}>
            <Command>
                <CommandInput placeholder={placeholder} />
                <CommandList>
                    <CommandEmpty>{empty_message}</CommandEmpty>
                    {for group in groups {
                        <CommandGroup key={group.heading} heading={group.heading}>
                            {for item in group.items {
                                def handle_item_select(current_value: str) {
                                    if item.on_select {
                                        item.on_select();
                                    }
                                }
                                <CommandItem
                                    key={item.label}
                                    className="cursor-pointer"
                                    onSelect={handle_item_select}
                                >
                                    {shortcut_menu_icon(item.icon_name)}
                                    <span>{item.label}</span>
                                    {if item.shortcut {
                                        <CommandShortcut>{item.shortcut}</CommandShortcut>
                                    }}
                                </CommandItem>
                            }}
                        </CommandGroup>
                    }}
                </CommandList>
            </Command>
        </CommandDialog>
    </div>
}

