# from: thangdevalone__modern-ui::hooks/use-media-query.js
import from "react" { useEffect }

obj MediaQueryListEvent {
    has matches: bool = False;
}

obj MediaQueryList {
    has matches: bool = False;
    def addEventListener(event: str, listener: Callable[[MediaQueryListEvent], None]);
    def removeEventListener(event: str, listener: Callable[[MediaQueryListEvent], None]);
    def addListener(listener: Callable[[MediaQueryListEvent], None]);
    def removeListener(listener: Callable[[MediaQueryListEvent], None]);
}

def:pub useMediaQuery(query: str) -> bool {
    has matches: bool = False;

    useEffect(lambda {
        if not window {
            return;
        }
        media = window.matchMedia(query) as MediaQueryList;
        matches = media.matches;
        listener = lambda (event: MediaQueryListEvent) {
            matches = event.matches;
        };
        if media.addEventListener {
            media.addEventListener("change", listener);
        } else {
            media.addListener(listener);
        }
        return lambda {
            if media.removeEventListener {
                media.removeEventListener("change", listener);
            } else {
                media.removeListener(listener);
            }
        };
    }, [query]);

    matches
}

