# from: 1146345502__aural-oss::components/ui/coach-speaking-wave.tsx
import from "@/lib/utils" { cn }
import from "react" { useEffect }
import math;

type CoachSpeakingPhase = str;

glob BAR_COUNT: int = 20;

glob MAX_HALF_PX: int = 18;

def:pub CoachSpeakingWave(phase: CoachSpeakingPhase, className: str = "") -> JsxElement {
    has tick: int = 0;

    useEffect(lambda {
        intervalId = setInterval(lambda { tick = tick + 1; }, 150);
        return lambda { clearInterval(intervalId); };
    }, []);

    level = 0.55 if phase == "playing" else 0.35;

    <div
        className={cn(
            "flex h-10 w-[152px] shrink-0 items-center justify-end",
            className,
        )}
        role="status"
        aria-label={"Coach preparing" if phase == "loading" else "Coach speaking"}
    >
        {if phase == "loading" {
            <div
                className="h-4 w-4 animate-spin rounded-full border-2 border-primary border-t-transparent"
                aria-hidden={True}
            />
        } else {
            <div className="relative flex h-10 w-full items-center">
                <div className="pointer-events-none absolute inset-x-0 top-1/2 border-t border-dotted border-primary/30" />
                <div className="relative flex h-10 w-full items-center justify-between gap-[2px]">
                    {for i in range(BAR_COUNT) {
                        barVariance = math.sin((i + tick) * 0.7) * 0.3 + 0.7;
                        halfH = max(2, int(level * barVariance * MAX_HALF_PX));
                        <div
                            key={str(i)}
                            className="w-[6px] flex-none rounded-full bg-primary transition-[height] duration-150"
                            style={{"height": f"{halfH * 2}px"}}
                        />
                    }}
                </div>
            </div>
        }}
    </div>
}

