# from: 1146345502__aural-oss::app/api/v1/_lib/interview-access.ts
import from "@/lib/api-key-auth" { apiError }
import from "@/lib/supabase/admin" { supabaseAdmin }

async def:pub assertInterviewProjectAccess(interviewId: str, projectIds: list[str]) -> dict[str, str] | Response {
    query = await supabaseAdmin.from("interviews").select("projectId").eq("id", interviewId).single();
    interview = query.data;
    error = query.error;
    if error or not interview {
        return apiError("NOT_FOUND", "Interview not found", 404);
    }
    if not (interview.projectId in projectIds) {
        return apiError("FORBIDDEN", "You do not have access to this interview", 403);
    }
    return {"projectId": interview.projectId as str};
}

