        }
    }
    <CheckboxPrimitiveRoot
        data-slot="checkbox"
        checked={checked_val}
        indeterminate={indeterminate}
        defaultChecked={default_val}
        onCheckedChange={handle_change}
        id={id}
        className={className if className else "peer border-input dark:bg-input/30 data-[checked]:bg-primary data-[checked]:text-primary-foreground data-[indeterminate]:text-foreground dark:data-[checked]:bg-primary data-[checked]:border-primary focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive group size-4 shrink-0 rounded-[4px] border shadow-xs transition-shadow outline-none focus-visible:ring-[3px] disabled:cursor-not-allowed disabled:opacity-50"}
