def getChildRef(child: object) -> object | None {
    child_dict = child as dict[str, object];
    return child_dict["ref"] if "ref" in child_dict else None;
}

def buildMergedProps(slotProps: dict[str, object], childProps: dict[str, object], childRef: object | None, forwardedRef: object) -> dict[str, object] {
    merged = mergeProps(slotProps, childProps);
    composedRef = composeRefs(forwardedRef, childRef) if forwardedRef else childRef;
    return {**merged, "ref": composedRef};
}

def mergeProps(slotProps: dict[str, object], childProps: dict[str, object]) -> dict[str, object] {
    overrideProps = {**childProps};
    return {**slotProps, **overrideProps};
}

