import from "./isCompletelyVisible.jac" { isCompletelyVisible }

obj SliderTarget {
    has scrollLeft: float = 0;
    has scrollWidth: float = 0;
    has parentElement: SliderTarget | None = None;
    has offsetLeft: float = 0;
    has clientWidth: float = 0;

    def scrollTo(horizontalPosition: float, verticalPosition: float) {
        return;
    }

    def querySelectorAll(selector: str) -> list[SliderTarget] {
        return [];
    }
}

def scrollSliderTo(slider: SliderTarget, horizontalPosition: float) {
    verticalPosition = 0;
    slider.scrollTo(horizontalPosition, verticalPosition);
}

def:pub scrollSliderNext(slider: SliderTarget) {
    slides = slider.querySelectorAll(".carousel__slide");
    firstVisibleSlide: SliderTarget | None = None;
    firstNotVisibleSlideAfterVisibleSlide: SliderTarget | None = None;
    for slide in slides {
        if not firstVisibleSlide and isCompletelyVisible(slide) {
            firstVisibleSlide = slide;
        }
        if firstVisibleSlide and not isCompletelyVisible(slide) {
            firstNotVisibleSlideAfterVisibleSlide = slide;
            break;
        }
    }
    initialScrollPosition = 0.0;
    if firstNotVisibleSlideAfterVisibleSlide {
        position = firstNotVisibleSlideAfterVisibleSlide.offsetLeft;
    } else {
        position = initialScrollPosition;
    }
    scrollSliderTo(slider, position);
}

def:pub scrollSliderPrevious(slider: SliderTarget) {
    if slider.scrollLeft == 0 {
        scrollSliderTo(slider, slider.scrollWidth);
        return;
    }
    slides = slider.querySelectorAll(".carousel__slide");
    firstVisibleSlideIndex: int | None = None;
    for (index, slide) in enumerate(slides) {
        if isCompletelyVisible(slide) {
            firstVisibleSlideIndex = index;
            break;
        }
    }
    if firstVisibleSlideIndex is None {
        return;
    }
    if not slider.parentElement {
        raise Exception("Could not find carousel div");
    }
    slideToScrollTo = slides[firstVisibleSlideIndex];
    position = slideToScrollTo.offsetLeft;
    scrollSliderTo(slider, position);
}

