import from "@/lib/utils" { cn }

def:pub Rating03(
    value: int | None = None,
    defaultValue: int | None = None,
    onValueChange: Callable[[int], None] | None = None,
    max: int = 10,
    lowLabel: str = "Extremely difficult",
    highLabel: str = "Extremely easy",
    readOnly: bool = False,
    disabled: bool = False,
    className: str = "",
    props: dict[str, object] = {},
) -> JsxElement {
    has internalValue: int | None = defaultValue;
    has name: str = "rating03";

    isControlled = value is not None;
    currentValue = value if isControlled else internalValue;
    isInteractive = not readOnly and not disabled;

    def commit_value(next: int) {
        if not isControlled {
            internalValue = next;
        }
        if onValueChange {
            onValueChange(next);
        }
    }

    def handle_change(index: int) {
        if isInteractive {
            commit_value(index);
        }
    }

    <div className={cn("flex flex-col gap-3", className)} {**props}>
        <div className="flex items-center justify-between text-sm text-muted-foreground">
            <span>{lowLabel}</span>
            <span>{highLabel}</span>
        </div>
        <div
            role="radiogroup"
            aria-label={"Rating: " + (str(currentValue) if currentValue is not None else "none") + " out of " + str(max)}
            aria-disabled={disabled if disabled else None}
            className={cn(
                "flex items-center justify-between gap-1",
                "pointer-events-none opacity-50" if disabled else "",
            )}
        >
            {for index in range(max + 1) {
                isSelected = currentValue == index;
                <label key={str(index)} className="flex flex-1 flex-col items-center gap-2">
                    <span className="text-sm text-muted-foreground">{index}</span>
                    <input
                        type="radio"
                        name={name}
                        value={str(index)}
                        checked={isSelected}
                        disabled={disabled}
                        readOnly={readOnly}
                        onChange={lambda { handle_change(index); }}
                        aria-label={str(index) + " out of " + str(max)}
                        className={cn(
                            "size-5 shrink-0 appearance-none rounded-full border-2 border-muted-foreground/40 transition-colors",
                            "checked:border-emerald-600 checked:bg-emerald-600",
                            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
                            "cursor-pointer hover:border-emerald-600/70" if isInteractive else "",
                        )}
                    />
                </label>
            }}
        </div>
    </div>
}

