import from "vitest" { expect }
import from "@/contrib/keybindings" { encodeKeyboardEvent, normalizeKey }

def newDecodedKey(overrides: dict[str, object]) -> dict[str, object] {
    base = {
        "key": "",
        "ctrlKey": False,
        "shiftKey": False,
        "altKey": False,
        "metaKey": False,
        "getModifierState": lambda (key: str) -> bool { return key in ["Control", "Shift", "Alt", "Meta"]; }
    };
    return {**base, **overrides};
}

test "normalizeKey" {
    expect(normalizeKey("J")).toEqual("j");
    expect(normalizeKey("Space")).toEqual("space");
    expect(normalizeKey("Alt+J")).toEqual("alt+j");
    expect(normalizeKey("Alt+Ctrl+J")).toEqual("ctrl+alt+j");
    expect(normalizeKey("Alt + Shift + Ctrl + Meta + Down")).toEqual("ctrl+shift+alt+meta+arrowdown");
    expect(lambda { normalizeKey(" "); }).toThrow("Invalid keybinding, empty key.");
    expect(lambda { normalizeKey("Alt+Shift+Ctrl+Mata+Down"); }).toThrow('Invalid keybinding "Alt+Shift+Ctrl+Mata+Down", unknown modifier "mata+"');
}

test "encodeKeyboardEvent" {
    expect(encodeKeyboardEvent(newDecodedKey({"key": "Unidentified"}))).toBeUndefined();
    expect(encodeKeyboardEvent(newDecodedKey({"key": "Alt"}))).toBeUndefined();
    expect(encodeKeyboardEvent(newDecodedKey({"key": "J"}))).toEqual("j");
    expect(encodeKeyboardEvent(newDecodedKey({"key": "J", "altKey": True}))).toEqual("alt+j");
}

