            profile_image = pic if pic is not None else f"https://avatar.vercel.sh/{given}";
            root ++> User(
                email=email_val,
                first_name=given,
                last_name=family,
                profile_image=profile_image,
            );
        }
        report "https://airbnb-yt-peach.vercel.app";
    }
}

def _auth_session_user() -> AuthSessionUser | None {
    token = get_current_auth();
    if token == "" {
        return None;
    }
    payload = jwt.decode(token, options={"verify_signature": False}) as dict[str, object];
    user_id = payload["sub"] as str if "sub" in payload else "";
    if user_id == "" {
        return None;
    }
    profile = payload["profile"] as dict[str, object] if "profile" in payload else {};
    email: str | None = None;
    if "identities" in payload {
        identities = payload["identities"] as list[dict[str, str]];
        for ident in identities {
            if ident["type"] == "email" {
                email = ident["value"];
            }
        }
    }
    given_name = profile["firstname"] as str if "firstname" in profile else None;
    family_name = profile["lastname"] as str if "lastname" in profile else None;
    picture = profile["avatar"] as str if "avatar" in profile else None;
    return AuthSessionUser(
        id=user_id,
        email=email,
        given_name=given_name,
        family_name=family_name,
        picture=picture,
    );
}

@restspec(method=HTTPMethod.GET, path="/api/auth/creation")
def:priv GET() -> str {
    user = _auth_session_user();
    if user is None or user.id == "" {
        raise Exception("Smoething went wrong, i am srorry....");
    }
    result = root spawn ensure_app_user(auth_user=user);
    return result.reports[0] as str;
}

