# from: travisjneuman__neumanos::utils/hashtags.ts
import re;

glob HASHTAG_PATTERN = re.compile(r"#(\[\[.*?\]\]|[a-zA-Z][a-zA-Z0-9-]*)");

def isValidHashtag(tag: str) -> bool {
    if not tag {
        return False;
    }
    if tag.isdigit() {
        return False;
    }
    return True;
}

def:pub extractHashtags(content: str) -> list[str] {
    tags: list[str] = [];
    pattern = re.compile(HASHTAG_PATTERN.pattern);
    for `match in pattern.finditer(content) {
        rawTag: str = `match.group(1).strip();
        tag: str = rawTag;
        if tag.startswith("[[") and tag.endswith("]]") {
            tag = (tag[2:-2]).strip();
        }
        tag = re.sub(r"[.,;:!?]$", "", tag);
        if tag and isValidHashtag(tag) and (tag not in tags) {
            tags = tags + [tag];
        }
    }
    return tags;
}

def:pub createHashtag(tag: str) -> str {
    if " " in tag {
        return f"#[[{tag}]]";
    }
    return f"#{tag}";
}

