# from: thangdevalone__modern-ui::hooks/use-debounce.js
import from "react" { useEffect }

def:pub useDebounce[T](value: T, delay: int) -> T {
    has debounced_value: T = value;

    useEffect(lambda {
        handler = setTimeout(lambda { debounced_value = value; }, delay);
        return lambda { clearTimeout(handler); };
    }, [value, delay]);

    debounced_value
}

