import from "./types.jac" { createWarning, Warning }
import from "./context.jac" { isDefaultOverflowValue }

glob RULE_ID = "inline-no-overflow";

def warn(fields: dict[str, str]) -> Warning {
    return createWarning(RULE_ID, fields);
}

def describeOverflow(overflowX: str, overflowY: str) -> str {
    if overflowX == overflowY {
        return f"overflow is \"{overflowX}\"";
    }
    if isDefaultOverflowValue(overflowX) {
        return f"overflow-y is \"{overflowY}\"";
    }
    if isDefaultOverflowValue(overflowY) {
        return f"overflow-x is \"{overflowX}\"";
    }
    return f"overflow-x is \"{overflowX}\" and overflow-y is \"{overflowY}\"";
}

