glob BAR_COUNT: int = 20;

enum AudioState: str {
    CONNECTING = "connecting",
    LISTENING = "listening",
    SPEAKING = "speaking",
}

def:pub AudioFrqCard() -> JsxElement {
    has bars: list[float] = [20.0 for _ in range(BAR_COUNT)];
    has state: AudioState = AudioState.SPEAKING;

    useEffect(lambda {
        def tick() -> None {
            min_h = 5.0;
            max_h = 20.0;
            if state == AudioState.LISTENING {
                min_h = 20.0;
                max_h = 60.0;
            }
            if state == AudioState.SPEAKING {
                min_h = 40.0;
                max_h = 90.0;
            }
            bars = [Math.random() * (max_h - min_h) + min_h for _ in range(BAR_COUNT)];
        }
        interval = setInterval(tick, 150);
        return lambda { clearInterval(interval); };
    }, [state]);

    def set_connecting(e: MouseEvent) -> None {
        state = AudioState.CONNECTING;
    }

    def set_listening(e: MouseEvent) -> None {
        state = AudioState.LISTENING;
    }

    def set_speaking(e: MouseEvent) -> None {
        state = AudioState.SPEAKING;
    }

    <div className="max-w-sm mx-auto px-4 w-full">
        <Card>
            <CardHeader>
                <CardTitle>Audio Frequency Visualizer</CardTitle>
                <CardDescription>
                    Real-time frequency band visualization with animated state
                    transitions
                </CardDescription>
            </CardHeader>
            <CardContent>
                <div
                    data-state={state}
                    className="relative flex justify-center gap-1.5 items-end w-full overflow-hidden rounded-lg bg-muted p-4 h-40 max-w-full"
                >
                    {for (i, height) in enumerate(bars) {
                        highlighted = state == AudioState.SPEAKING;
                        <div
                            key={str(i)}
                            data-highlighted={highlighted}
                            className={"max-w-3 min-w-2 flex-1 transition-all duration-150 rounded-full " + ("bg-chart-3" if highlighted else "bg-border dark:bg-gray-200/20")}
                            style={{"height": f"{height}%"}}
                        />
                    }}
                </div>
            </CardContent>
            <CardFooter className="flex items-center gap-2">
                <Button variant={"default" if state == AudioState.CONNECTING else "outline"} size="sm" onClick={set_connecting} className="cursor-pointer">
                    Connecting
                </Button>
                <Button variant={"default" if state == AudioState.LISTENING else "outline"} size="sm" onClick={set_listening} className="cursor-pointer">
                    Listening
                </Button>
                <Button variant={"default" if state == AudioState.SPEAKING else "outline"} size="sm" onClick={set_speaking} className="cursor-pointer">
                    Speaking
                </Button>
            </CardFooter>
        </Card>
    </div>
}

