def getBadgeStyles(text: str) -> str {
    lowercaseText = text.lower();
    if "%" in lowercaseText or lowercaseText == "sale" {
        return "bg-red-500/10 text-red-500";
    }
    if lowercaseText == "new" {
        return "bg-blue-500/10 text-blue-500";
    }
    if lowercaseText == "hot" {
        return "bg-orange-400/10 text-orange-400";
    }
    return "bg-primary/10 text-primary";
}

def:pub ProductCard(
    image: str,
    category: str,
    name: str,
    rating: float,
    reviews: int,
    price: int,
    originalPrice: int | None = None,
    badge: ProductCardBadge | None = None,
    className: str | None = None,
    onAddToCart: Callable[[], None] | None = None,
    onWishlist: Callable[[], None] | None = None
) -> JsxElement {
    has isWishlisted: bool = False;

    def handle_wishlist(e: MouseEvent) {
        isWishlisted = not isWishlisted;
        if onWishlist {
            onWishlist();
        }
    }

    def handle_add_to_cart(e: MouseEvent) {
        if onAddToCart {
            onAddToCart();
        }
    }

    <Card className={cn("group flex flex-col gap-0 rounded-2xl bg-card p-0 transition-all overflow-hidden ring-0 border", className)}>
        <div className="relative overflow-hidden bg-muted/50 min-h-55 h-full">
            {if badge is not None {
                <Badge
                    variant="outline"
                    className={cn(
                        "absolute left-4 top-5.5 z-10 rounded-full border-0 px-2 py-0.5 text-xs capitalize",
                        getBadgeStyles(badge.text)
                    )}
                >
                    {badge.text}
                </Badge>
            }}
            <Button
                size="icon-sm"
                className="group/wishlist absolute right-4 top-4 z-10 size-8 rounded-full bg-background transition-transform hover:scale-110 cursor-pointer"
                onClick={handle_wishlist}
            >
                <Heart
                    className={cn(
                        "size-4 transition-all duration-300",
                        "fill-red-500 text-red-500 scale-110" if isWishlisted else "text-foreground"
                    )}
                />
                <span className="sr-only">Add to wishlist</span>
            </Button>
            <img
                src={image}
                alt={name}
                className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
            />
        </div>
        <CardContent className="flex flex-col gap-3 p-5">
            <div className="flex flex-col gap-2">
                <span className="text-sm text-muted-foreground capitalize">{category}</span>
                <p className="line-clamp-1 text-lg font-medium text-foreground">{name}</p>
                <div className="flex items-center gap-2">
                    <div className="flex items-center">
                        {for i in range(5) {
                            <Star
                                key={str(i)}
                                className={cn(
                                    "h-3.5 w-3.5",
                                    "fill-orange-400 text-orange-400" if i < int(rating) else "fill-muted text-orange-400"
                                )}
                            />
                        }}
                    </div>
                    <small className="text-sm text-foreground">{rating}</small>
