# from: aliezzahn__iranian-nid-validator::components/ui/progressive-blur.tsx
import from "..lib.utils" { cn }

glob:pub GRADIENT_ANGLES = {"top": 0, "right": 90, "bottom": 180, "left": 270};

def:pub ProgressiveBlur(
    direction: str = "bottom",
    blurLayers: int = 8,
    className: str = "",
    blurIntensity: float = 0.25
) -> JsxElement {
    layers = max(blurLayers, 2);
    segmentSize = 1.0 / (blurLayers + 1);

    <div className={cn("relative", className)}>
        {for index in range(layers) {
            angle = GRADIENT_ANGLES[direction];
            positions = [
                index * segmentSize,
                (index + 1) * segmentSize,
                (index + 2) * segmentSize,
                (index + 3) * segmentSize,
            ];
            gradientStops = [
                f"rgba(255, 255, 255, {1 if posIndex == 1 or posIndex == 2 else 0}) {pos * 100}%"
                for (posIndex, pos) in enumerate(positions)
            ];
            stopsJoined = ", ".join(gradientStops);
            gradient = f"linear-gradient({angle}deg, {stopsJoined})";

            <div
                key={str(index)}
                className="pointer-events-none absolute inset-0 rounded-[inherit]"
                style={{
                    "maskImage": gradient,
                    "WebkitMaskImage": gradient,
                    "backdropFilter": f"blur({index * blurIntensity}px)",
                }}
            />
        }}
    </div>
}

