def pluralizeNotes(number: float) -> str {
    if (number == 1) {
        return "1 note";
    }
    return f"{number} notes";
}

def:pub SearchLayout(props: SearchPageProps) -> JsxElement {
    site = props.site;
    has value: str = "";
    swr = useSearch(value);
    notes = swr.data;
    error = swr.error;
    isValidating = swr.isValidating;

    def handle_submit(e: FormEvent) {
        e.preventDefault();
    }

    def handle_change(e: ChangeEvent) {
        value = e.target.value;
    }

    <>
        <Header name={site.name} headline={site.headline} />
        <form role="search" className={styles.form} onSubmit={handle_submit}>
            <label htmlFor="search">Search</label>
            <div>
                <input
                    id="search"
                    value={value}
                    onChange={handle_change}
                    placeholder="Search your notes"
                    autoFocus={True}
                    className="placeholder-gray-900"
                />
                <FaSearch />
            </div>
            {if notes {
                <small>
                    Found {pluralizeNotes(len(notes))} from a total of {pluralizeNotes(site.total_notes)}.
                </small>
            }}
            {if error {
                <p>{str(error)}</p>
            }}
            {if isValidating {
                <FaSpinner />
            }}
            <ul>
                {for note in (notes if notes else []) {
                    <NoteItem key={note.path} note={note} />
                }}
            </ul>
        </form>
    </>
}

