def getStarColor(score: float) -> str {
    if (score < 3) {
        return "text-red-500";
    }
    if (score < 5) {
        return "text-orange-500";
    }
    if (score < 7) {
        return "text-yellow-500";
    }
    if (score < 8.5) {
        return "text-green-500";
    }
    return "text-emerald-400";
}

