    if (score < 3) {
        return "bg-red-950";
    }
    if (score < 5) {
        return "bg-orange-950";
    }
    if (score < 7) {
        return "bg-yellow-950";
    }
    if (score < 8.5) {
        return "bg-green-950";
    }
    return "bg-emerald-950";
}

