def:pub readTheme() -> dict[str, str] | None {
    data = localStorage.getItem(themeKey);
    if data is not None {
        try {
            result = JSON.parse(data) as dict[str, str];
        } except Exception {
            console.error("Failed to read theme");
            return None;
        }
        return result;
    }
    return None;
}

def:pub writeTheme(theme: dict[str, str]) {
    json = JSON.stringify(theme);
    localStorage.setItem(themeKey, json);
}

# language: jac
# from: avrcoelho__react-hook-notification::presentation/components/Container/useController.ts
glob DELAY = 2000;
glob timerId: float | None = None;

def:pub useController(params: dict[str, object]) -> dict[str, object] {
    isVisible = params["isVisible"] as bool;
    has show: bool = False;

    import from "react" { useEffect, useRef }
    showRef = useRef(False);

    useEffect(lambda {
        if timerId is not None {
            clearTimeout(timerId);
        }
        if isVisible {
            showRef.current = True;
            show = True;
        } else {
            timerId = setTimeout(lambda { show = False; }, DELAY) as float;
        }
        return lambda {
            if timerId is not None {
                clearTimeout(timerId);
            }
        };
    }, [isVisible]);

    return {"show": show};
}

