import from "motion/react" { motion, AnimatePresence }
import from "lucide-react" { Hash }
import from "@/components/ui/pagination" {
    Pagination,
    PaginationContent,
    PaginationItem,
    PaginationNext,
    PaginationPrevious,
}
import from "@/components/ui/input" { Input }
import from "@/components/ui/button" { Button }

def:pub InteractiveJump() -> JsxElement {
    has active_page: int = 12;
    has is_editing: bool = False;
    has input_value: str = "12";
    total_pages = 48;

    def handle_page_change(page: int) {
        new_page = max(1, min(total_pages, page));
        active_page = new_page;
        input_value = str(new_page);
        is_editing = False;
    }

    def handle_input_submit(e: FormEvent) {
        e.preventDefault();
        try {
            page = int(input_value);
            handle_page_change(page);
        } except ValueError {
            input_value = str(active_page);
            is_editing = False;
        }
    }

    def handle_prev(e: MouseEvent) {
        e.preventDefault();
        handle_page_change(active_page - 1);
    }

    def handle_next(e: MouseEvent) {
        e.preventDefault();
        handle_page_change(active_page + 1);
    }

    def start_editing(e: MouseEvent) {
        is_editing = True;
    }

    def handle_input_change(e: ChangeEvent) {
        input_value = e.target.value;
    }

    def handle_input_blur(e: FocusEvent) {
        is_editing = False;
    }

    <Pagination className="justify-center">
        <PaginationContent className="bg-background border p-1.5 rounded-xl gap-2">
            <PaginationItem>
                <PaginationPrevious
                    href="#"
                    onClick={handle_prev}
                    className="hover:bg-secondary/80 rounded-lg group"
                />
            </PaginationItem>
            <div className="flex items-center px-2 min-w-[140px] justify-center">
                <AnimatePresence mode="wait">
                    {if not is_editing {
                        <motion.div
                            key="viewer"
                            initial={{"opacity": 0, "y": 5}}
                            animate={{"opacity": 1, "y": 0}}
                            exit={{"opacity": 0, "y": -5}}
                            onClick={start_editing}
                            className="flex items-center gap-1.5 cursor-pointer hover:bg-secondary/50 px-3 py-1 rounded-md transition-colors group"
                        >
                            <span className="text-sm font-semibold tabular-nums">{active_page}</span>
                            <span className="text-xs text-muted-foreground font-medium uppercase tracking-wider">
                                of {total_pages}
                            </span>
                            <Hash className="w-3 h-3 text-muted-foreground group-hover:text-primary transition-colors" />
                        </motion.div>
                    } else {
                        <motion.form
                            key="editor"
                            initial={{"opacity": 0, "scale": 0.95}}
                            animate={{"opacity": 1, "scale": 1}}
                            exit={{"opacity": 0, "scale": 0.95}}
                            onSubmit={handle_input_submit}
                            className="flex items-center gap-1.5"
                        >
                            <Input
                                autoFocus={True}
                                className="w-12 h-7 py-0 px-1 text-center text-xs tabular-nums focus-visible:ring-1"
                                value={input_value}
                                onChange={handle_input_change}
                                onBlur={handle_input_blur}
                                type="text"
                                inputMode="numeric"
                            />
                            <Button type="submit" variant="secondary" size="sm" className="h-7 px-2 text-[10px] font-bold uppercase tracking-tighter cursor-pointer">
                                GO
                            </Button>
                        </motion.form>
                    }}
                </AnimatePresence>
            </div>
            <PaginationItem>
                <PaginationNext
                    href="#"
                    onClick={handle_next}
                    className="hover:bg-secondary/80 rounded-lg group"
                />
            </PaginationItem>
        </PaginationContent>
    </Pagination>
}

