import from "react" { useEffect, useState }

def:pub useDebounce[T](value: T, delayMs: float) -> T {
    _jx_d0 = useState(value);
    debouncedValue = _jx_d0[0] as T;
    setDebouncedValue = _jx_d0[1];
    useEffect(lambda () -> object {
        timeoutId = window.setTimeout(lambda () -> object {
            setDebouncedValue(value);
        }, delayMs);
        return lambda () -> object {
            window.clearTimeout(timeoutId);
        };
    }, [value, delayMs]);
    return debouncedValue;
}

