def:pub Header(navigationData: list[NavigationSection], className: str = "") -> JsxElement {
    has sticky: bool = False;
    has isOpen: bool = False;

    def handle_scroll() -> None {
        sticky = window.scrollY >= 50;
    }

    def handle_resize() -> None {
        if window.innerWidth >= 768 {
            isOpen = False;
        }
    }

    def handle_open_change(open: bool) -> None {
        isOpen = open;
    }

    useEffect(lambda {
        window.addEventListener("scroll", handle_scroll);
        window.addEventListener("resize", handle_resize);
        return lambda {
            window.removeEventListener("scroll", handle_scroll);
            window.removeEventListener("resize", handle_resize);
        };
    }, []);

    <motion.header
        initial={{"opacity": 0, "y": -32}}
        animate={{"opacity": 1, "y": 0}}
        transition={{"duration": 0.7, "ease": "easeInOut"}}
        className={cn(
            "inset-x-0 z-50 px-4 flex items-center justify-center sticky top-0 h-20",
            className,
        )}
    >
        <div
            className={cn(
                "w-full max-w-6xl flex items-center h-fit justify-between gap-3.5 lg:gap-6 transition-all duration-500",
                "p-2.5 bg-background/60 backdrop-blur-lg border border-border/40 shadow-2xl shadow-primary/5 rounded-full" if sticky else "bg-transparent border-transparent",
            )}
        >
            <div>
                <a href="#">
                    <Logo className="gap-3" />
                </a>
            </div>
            <div>
                <NavigationMenu className="max-lg:hidden bg-muted p-0.5 rounded-full">
                    <NavigationMenuList className="flex gap-0">
                        {for navItem in navigationData {
                            <NavigationMenuItem key={navItem.title}>
                                <NavigationMenuLink
                                    href={navItem.href}
                                    className="px-2 lg:px-4 py-2 text-sm font-medium rounded-full text-muted-foreground hover:text-foreground hover:bg-background outline outline-transparent hover:outline-border hover:shadow-xs transition tracking-normal"
                                >
                                    {navItem.title}
                                </NavigationMenuLink>
                            </NavigationMenuItem>
                        }}
                    </NavigationMenuList>
                </NavigationMenu>
            </div>
            <div className="flex items-center gap-3">
                <CollaborateButton className="max-lg:hidden" />
                <Sheet open={isOpen} onOpenChange={handle_open_change}>
                    <SheetTrigger className="lg:hidden">
                        <Icon icon="solar:hamburger-menu-linear" width={24} height={24} />
                    </SheetTrigger>
                    <SheetContent side="right" className="w-full sm:max-w-sm">
                        <SheetTitle className="sr-only">Navigation</SheetTitle>
                        <div className="flex flex-col gap-6 pt-8">
                            {for navItem in navigationData {
                                <SheetClose key={navItem.title} asChild={True}>
                                    <a href={navItem.href} className="text-lg font-medium">
                                        {navItem.title}
                                    </a>
                                </SheetClose>
                            }}
                            <CollaborateButton />
                        </div>
                    </SheetContent>
                </Sheet>
            </div>
        </div>
    </motion.header>
}

