glob prefixCls = "fam-result";

obj:pub ResultProps {
    has className: str | None = None;
    has style: dict[str, object] | None = None;
    has imgUrl: str | None = None;
    has imgType: str | None = None;
    has img: object | None = None;
    has title: object | None = None;
    has message: object | None = None;
    has expandNode: object | None = None;
    has empty: bool | None = None;
    has onClick: Callable[[], None] | None = None;
}

def:pub Result(
    className: str | None = None,
    style: dict[str, object] | None = None,
    title: object | None = None,
    message: object | None = None,
    img: object | None = None,
    imgUrl: str | None = None,
    imgType: str | None = None,
    expandNode: object | None = None,
    empty: bool = False,
    onClick: Callable[[], None] | None = None,
) -> JsxElement {
    wrapCls = classnames(prefixCls, className, {f"{prefixCls}-empty": empty});
    imgContent: object | None = None;
    if img {
        imgContent = <div className={f"{prefixCls}-img"}>{img}</div>;
    } elif imgUrl {
        imgContent = <div className={f"{prefixCls}-img"}><img src={imgUrl} /></div>;
    } elif imgType and imgType in icons {
        Icon = icons[imgType];
        imgContent = <div className={f"{prefixCls}-img"}><Icon /></div>;
    }
    def handleClick() {
        if onClick {
            onClick();
        }
    }
    <div className={wrapCls} style={style if style is not None else {}} onClick={handleClick}>
        {imgContent}
        {if title {
            <div className={f"{prefixCls}-title"}>{title}</div>
        }}
        {if message {
            <div className={f"{prefixCls}-message"}>{message}</div>
        }}
        {if expandNode {
            <div className={f"{prefixCls}-expand"}>{expandNode}</div>
        }}
    </div>
}

