import from "lucide-react" { Laptop, Moon, Sun }
import from "next-themes" { useTheme }
import from "@/components/modern-ui/button" { Button }
import from "@/components/modern-ui/dropdown-menu" { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger }

def:pub ThemeToggle() -> JsxElement {
    has mounted: bool = False;
    theme_ctx = useTheme();

    can with entry {
        mounted = True;
    }

    def render_icon() -> JsxElement | None {
        if not mounted {
            return None;
        }
        if theme_ctx.resolvedTheme == "dark" {
            return <Moon className="h-5 w-5" />;
        }
        if theme_ctx.resolvedTheme == "light" {
            return <Sun className="h-5 w-5" />;
        }
        return <Laptop className="h-5 w-5" />;
    }

    <DropdownMenu>
        <DropdownMenuTrigger asChild={True}>
            <Button variant="ghost" size="icon" className="relative rounded-full" aria-label="Toggle theme">
                {render_icon()}
            </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={lambda { theme_ctx.setTheme("light"); }} className="flex items-center gap-2 cursor-pointer">
                <Sun className="h-4 w-4" />
                <span>Light</span>
            </DropdownMenuItem>
            <DropdownMenuItem onClick={lambda { theme_ctx.setTheme("dark"); }} className="flex items-center gap-2 cursor-pointer">
                <Moon className="h-4 w-4" />
                <span>Dark</span>
            </DropdownMenuItem>
            <DropdownMenuItem onClick={lambda { theme_ctx.setTheme("system"); }} className="flex items-center gap-2 cursor-pointer">
                <Laptop className="h-4 w-4" />
                <span>System</span>
            </DropdownMenuItem>
        </DropdownMenuContent>
    </DropdownMenu>
}

