def:pub parseNaturalLanguageDate(input: str, referenceDate: object = None) -> object | None {
    if (not input) or (not isinstance(input, str)) {
        return None;
    }
    trimmed = input.strip();
    if not trimmed {
        return None;
    }
    ref = referenceDate if referenceDate is not None else Date();
    parsed = chrono.parseDate(trimmed, ref);
    if (not parsed) or (isNaN(parsed.getTime())) {
        return None;
    }
    return parsed;
}

