import from "react" { useEffect }

glob VISIBLE_MS = 2600;

def:pub DraftPraise(praiseCount: int, className: str | None = None) -> JsxElement {
    has shownCount: int = 0;

    useEffect(lambda {
        if praiseCount == 0 {
            return lambda { };
        }
        shownCount = praiseCount;
        timer = setTimeout(lambda { shownCount = 0; }, VISIBLE_MS);
        return lambda { clearTimeout(timer); };
    }, [praiseCount]);

    if shownCount == 0 {
        return <></>;
    }

    return <output className={cn("coach-praise pointer-events-none absolute flex items-center gap-1.5 text-muted-foreground text-xs", className)}><Check className="size-3.5 text-green-600" aria-hidden="true" />Reads well so far</output>;
}

