obj OrbitIconData {
    has label: str;
    has bg_color: str;
    has text_color: str;
    has icon: JsxElement;
}

def children_to_list(children: JsxElement | list[JsxElement] | None) -> list[JsxElement] {
    if children is None {
        return [];
    }
    if isinstance(children, list) {
        return children;
    }
    return [children];
}

def:pub OrbitingCircleIcons(
    className: str = "",
    children: JsxElement | list[JsxElement] | None = None,
    reverse: bool = False,
    duration: float = 20.0,
    delay: float = 0.0,
    radius: float = 160.0,
    path: bool = True,
    icon_size: float = 0.0,
    speed: float = 1.0,
    props: dict[str, object] = {}
) -> JsxElement {
    calculated_duration = duration / speed;
    child_list = children_to_list(children);
    <>
        {if path {
            <svg xmlns="http://www.w3.org/2000/svg" version="1.1" className="pointer-events-none absolute inset-0 size-full">
                <circle className="stroke-black/10 stroke-1 dark:stroke-white/10" cx="50%" cy="50%" r={radius} fill="none" />
            </svg>
        }}
        {for (index, child) in enumerate(child_list) {
            angle = (360.0 / len(child_list)) * float(index);
            <div
                style={{
                    "--duration": f"{calculated_duration}s",
                    "--radius": f"{radius}px",
                    "--angle": f"{angle}deg",
                }}
                className={cn("animate-orbit", "reverse" if reverse else "", className)}
                {**props}
            >
                {child}
            </div>
        }}
    </>
}

