# from: prgrms-fe-devcourse__FEDC3_Bigtoria_Off::utils/calcCreatedToCurrentTime.ts
glob EXPIRED_LIMIT_DATE: int = 5;

def:pub calcCreatedToCurrentDate(createdAt: str) -> str {
    if createdAt == "" {
        return "";
    }
    curTime = new(Date);
    createdTime = new(Date, createdAt);
    elapsedTime = curTime.getTime() - createdTime.getTime();
    eDay = int(elapsedTime // (1000 * 60 * 60 * 24));
    eHour = int(elapsedTime // (1000 * 60 * 60));
    eMinutes = int(elapsedTime // (1000 * 60));
    if elapsedTime < 0 or eMinutes == 0 {
        return "방금 전";
    }
    if eDay == 0 {
        if eHour == 0 {
            return f"{eMinutes}분 전";
        }
        return f"{eHour}시간 전";
    }
    return f"{eDay}일 전";
}

def:pub isExpiredDate(createdAt: str) -> bool {
    if createdAt == "" {
        return True;
    }
    curTime = new(Date);
    createdTime = new(Date, createdAt);
    elapsedTime = curTime.getTime() - createdTime.getTime();
    eDay = int(elapsedTime // (1000 * 60 * 60 * 24));
    if eDay > EXPIRED_LIMIT_DATE {
        return True;
    }
    return False;
}

