def:pub isNew(dateString: str) -> bool {
    inputDate = new(Date, dateString);
    today = new(Date);
    diffMs = today.getTime() - inputDate.getTime();
    diffDays = diffMs / (1000 * 60 * 60 * 24);
    return diffDays <= 14;
}

