import from "@/lib/features/products/productsSlice" { Color, setColorSelection }
import from "@/lib/hooks/redux" { useAppDispatch, useAppSelector }
import from "@/lib/store" { RootState }
import from "@/lib/utils" { cn }
import from "react-icons/io" { IoMdCheckmark }

glob colorsData: list[dict[str, str]] = [{"name": "Brown", "code": "bg-[#4F4631]"}, {"name": "Green", "code": "bg-[#314F4A]"}, {"name": "Blue", "code": "bg-[#31344F]"}];

def:pub ColorSelection() -> JsxElement {
    productsSlice = useAppSelector(lambda (state: RootState) -> dict[str, object] { return state.products; });
    colorSelection = productsSlice["colorSelection"] as dict[str, str];
    dispatch = useAppDispatch();
    def handle_color_click(color: dict[str, str]) {
        dispatch(setColorSelection(color as Color));
    }
    <div className="flex flex-col">
        <span className="text-sm sm:text-base text-black/60 mb-4">Select Colors</span>
        <div className="flex items-center flex-wrap space-x-3 sm:space-x-4">
            {for color in colorsData {
                <button
                    type="button"
                    className={cn([color["code"], "rounded-full w-9 sm:w-10 h-9 sm:h-10 flex items-center justify-center"])}
                    onClick={lambda { handle_color_click(color); }}
                >
                    {if colorSelection["name"] == color["name"] {
                        <IoMdCheckmark className="text-base text-white" />
                    }}
                </button>
            }}
        </div>
    </div>
}

