import from "classnames" { default as classnames }
import from "../badge/index.jac" { Badge }

glob prefixCls = "fam-tabbar-item";

def:pub Item(
    className: str | None = None,
    style: dict[str, object] | None = None,
    icon: object = None,
    title: object = None,
    badge: str | int | None = None,
    dot: bool = False,
    onClick: Callable[[str], None] | None = None,
    selectedColor: str | None = None,
    activeKey: str | None = None,
    fkey: str | None = None,
) -> JsxElement {
    isSelected = activeKey is not None and activeKey == fkey;
    wrapCls = classnames(prefixCls, className, {f"{prefixCls}-active": isSelected});

    def handleOnClick(e: MouseEvent) {
        if onClick and fkey is not None {
            onClick(fkey);
        }
    }

    initContent = <div>
        {if icon {
            <div className={f"{prefixCls}-icon"}>{icon}</div>
        }}
        <div className={f"{prefixCls}-title"}>{title}</div>
    </div>;

    if badge {
        content = <Badge text={badge} className="fam-tab-bar-badge">{initContent}</Badge>;
    } elif dot {
        content = <Badge dot={True} className="fam-tab-bar-badge">{initContent}</Badge>;
    } else {
        content = initContent;
    }

    return <div className={wrapCls} style={style if style else {}} onClick={handleOnClick}>{content}</div>;
}

