# from: bishopZ__2026-Boilerplate::server/services/jwt.test.ts
import from "vitest" { describe, it, expect }
import from .jwt { signToken, verifyToken }

glob TEST_PAYLOAD: dict[str, str] = {"email": "alice@example.com", "name": "Alice"};

with entry {
    describe("signToken", lambda {
        it("returns a non-empty string", lambda {
            token: str = signToken(TEST_PAYLOAD);
            expect(type(token)).toBe(str);
            expect(len(token)).toBeGreaterThan(0);
        });
        it("produces a three-part JWT (header.payload.signature)", lambda {
            token: str = signToken(TEST_PAYLOAD);
            expect(token.split(".")).toHaveLength(3);
        });
    });
    describe("verifyToken", lambda {
        it("returns the original payload for a valid token", lambda {
            token: str = signToken(TEST_PAYLOAD);
            result: dict[str, str] | None = verifyToken(token);
            expect(result).not.toBeNull();
            expect(result["email"]).toBe(TEST_PAYLOAD["email"]);
            expect(result["name"]).toBe(TEST_PAYLOAD["name"]);
        });
        it("returns null for a malformed token string", lambda {
            expect(verifyToken("not-a-jwt")).toBeNull();
        });
        it("returns null for a token signed with a different secret", lambda {
            tamperedToken = "eyJhbGciOiJIUzI1NiJ9.eyJlbWFpbCI6InRlc3QifQ.wrongsig";
            expect(verifyToken(tamperedToken)).toBeNull();
        });
        it("returns null for an empty string", lambda {
            expect(verifyToken("")).toBeNull();
        });
    });
}

