def change_badge_class(change_type: str) -> str {
    if change_type == "feature" {
        return "bg-blue-500/10 text-blue-500 border-blue-500/20";
    } elif change_type == "improvement" {
        return "bg-teal-400/10 text-teal-400 border-teal-400/20";
    } elif change_type == "fix" {
        return "bg-orange-400/10 text-orange-400 border-orange-400/20";
    }
    return "bg-red-500/10 text-red-500 border-red-500/20";
}

def change_badge_label(change_type: str) -> str {
    if change_type == "feature" {
        return "Feature";
    } elif change_type == "improvement" {
        return "Improvement";
    } elif change_type == "fix" {
        return "Fix";
    }
    return "Breaking";
}

def:pub CollapsibleChangelog() -> JsxElement {
    has openVersions: list[str] = ["v3.2.0"];

    def toggle(version: str) {
        if version in openVersions {
            openVersions = [v for v in openVersions if v != version];
        } else {
            openVersions = openVersions + [version];
        }
    }

    <div className="w-full max-w-lg space-y-2">
        {for release in releases {
            <Collapsible
                key={release["version"]}
                open={release["version"] in openVersions}
                onOpenChange={lambda { toggle(release["version"] as str); }}
            >
                <div className="rounded-xl outline bg-background overflow-hidden">
                    <CollapsibleTrigger className="w-full flex justify-between px-4 py-3 h-auto rounded-none hover:bg-muted/50">
                        <div className="flex items-center gap-3">
                            <span className="font-semibold text-foreground">
                                release["version"];
                            </span>
                            <span className="text-sm text-muted-foreground">
                                release["date"];
                            </span>
                        </div>
                        <ChevronDown className={cn("size-4 text-muted-foreground transition-transform", "rotate-180" if release["version"] in openVersions else "")} />
                    </CollapsibleTrigger>
                    <CollapsibleContent>
                        <div className="px-4 pb-3 space-y-2">
                            {for change in release["changes"] as list[dict[str, str]] {
                                <div key={change["description"]} className="flex items-start gap-2">
                                    <Badge variant="outline" className={cn("gap-1", change_badge_class(change["type"]))}>
                                        {if change["type"] == "feature" {
                                            <Rocket className="size-3" />;
                                        } elif change["type"] == "improvement" {
                                            <Zap className="size-3" />;
                                        } elif change["type"] == "fix" {
                                            <Bug className="size-3" />;
                                        } else {
                                            <Wrench className="size-3" />;
                                        }}
                                        change_badge_label(change["type"]);
                                    </Badge>
                                    <span className="text-sm text-muted-foreground">
                                        change["description"];
                                    </span>
                                </div>
                            }}
                        </div>
                    </CollapsibleContent>
                </div>
            </Collapsible>
        }}
    </div>
}

