# from: stackrender__stackrender::hooks/use-disclosure.ts
import from "react" { useCallback, useState }

def:pub useDisclosure(initial: bool = False) -> dict {
    state = useState(initial);
    isOpen = state[0];
    setIsOpen = state[1];
    onOpen = useCallback(lambda { setIsOpen(True); }, []);
    onClose = useCallback(lambda { setIsOpen(False); }, []);
    onToggle = useCallback(lambda { setIsOpen(lambda (prev: bool) -> bool { return not prev; }); }, []);
    return {"isOpen": isOpen, "onOpen": onOpen, "onClose": onClose, "onToggle": onToggle};
}

