# from: shadcnspace__shadcnspace::components/shadcn-space/animated-text/animated-text-03.tsx
import from "react" { useEffect }

glob TYPING_WORDS: list[str] = [
    "Hello, World!",
    "Welcome to my website!",
    "This is a typewriter effect."
];

def:pub AnimatedTypingMotion() -> JsxElement {
    has i: int = 0;
    has j: int = 0;
    has isDeleting: bool = False;
    has text: str = "";

    useEffect(lambda {
        currentWord = TYPING_WORDS[i];
        timeout = setTimeout(lambda {
            if isDeleting {
                text = currentWord[0:j - 1];
                j = j - 1;
                if j == 0 {
                    isDeleting = False;
                    i = (i + 1) % len(TYPING_WORDS);
                }
            } else {
                text = currentWord[0:j + 1];
                j = j + 1;
                if j == len(currentWord) {
                    isDeleting = True;
                }
            }
        }, 100);
        return lambda { clearTimeout(timeout); };
    }, [i, j, isDeleting]);

    <div className="w-full flex justify-start items-center">
        <p className="text-xl sm:text-2xl font-medium text-foreground">{text}</p>
    </div>
}

