def:pub CopyButton(value: str, className: str = "") -> JsxElement {
    has hasCopied: bool = False;

    async def handleCopy(_e: MouseEvent) {
        await navigator.clipboard.writeText(value);
        hasCopied = True;
        setTimeout(lambda { hasCopied = False; }, 2000);
    }

    <button
        onClick={handleCopy}
        className={cn("group relative rounded-md p-1.5 text-zinc-400", className)}
        aria-label="Copy command"
