async def:pub generateMetadata(props: dict[str, object]) -> dict[str, str] {
    params = props["params"];
    resolved = await params;
    projectId = resolved["projectId"] as str;
    caller = appRouter.createCaller({"auth": await auth()});
    projectName = "Project";
    try {
        project = await caller.projects.getOne({"id": projectId});
        projectName = project.name as str;
    } except TRPCError as error {
        projectName = error.message as str;
    }
    return {
        "description": f"View the project {projectName} and its messages.",
        "title": projectName
    };
}

