    params = props["params"];
    resolved = await params;
    projectId = resolved["projectId"] as str;
    queryClient = getQueryClient();
    queryClient.prefetchQuery(trpc.messages.getMany.queryOptions({"projectId": projectId}));
    queryClient.prefetchQuery(trpc.projects.getOne.queryOptions({"id": projectId}));
    <HydrationBoundary state={dehydrate(queryClient)}>
        <ErrorBoundary fallbackRender={render_project_error}>
            <Suspense fallback={<ProjectViewLoading />}>
                <ProjectView projectId={projectId} />
            </Suspense>
        </ErrorBoundary>
    </HydrationBoundary>
}

