# from: dancing-team__dance-ui::components/src/CountDown/script/util.ts
import from datetime { datetime }
import from re { sub, Match }

def:pub formatDate(time: datetime | None, format: str = "") -> str {
    date = time if time else datetime.now();
    map: dict[str, str] = {
        "y": str(date.year),
        "M": str(date.month),
        "d": str(date.day),
        "H": str(date.hour),
        "m": str(date.minute),
        "s": str(date.second),
    };
    for i in map {
        if int(map[i]) < 10 {
            map[i] = "0" + map[i];
        }
    }
    fmt = format if format else "yyyy-MM-dd HH:mm:ss";
    def repl(m: Match[str]) -> str {
        v = m.group(0);
        if "y" in v {
            y = map["y"];
            pad = 4 - len(v);
            return y[pad:];
        }
        key = v[0:1];
        return map[key];
    }
    return sub("y+|M+|d+|H+|m+|s+", repl, fmt);
}

