import from "react" { useEffect, useState }

glob QUERY = "(prefers-reduced-motion: reduce)";

obj MediaQueryListEvent {
    has matches: bool;
}

obj MediaQueryList {
    has matches: bool;
    def addEventListener(event: str, handler: Callable[[MediaQueryListEvent], None]);
    def removeEventListener(event: str, handler: Callable[[MediaQueryListEvent], None]);
}

def _initial_reduced() -> bool {
    mql = window.matchMedia(QUERY) as MediaQueryList;
    return mql.matches;
}

def:pub useReducedMotion() -> bool {
    pair = useState(_initial_reduced);
    reduced = pair[0] as bool;
    set_reduced = pair[1] as Callable[[bool], None];

    useEffect(lambda {
        mql = window.matchMedia(QUERY) as MediaQueryList;
        def on_change(e: MediaQueryListEvent) {
            set_reduced(e.matches);
        }
        set_reduced(mql.matches);
        mql.addEventListener("change", on_change);
        return lambda { mql.removeEventListener("change", on_change); };
    }, []);

    return reduced;
}

