import from "@/types/definition" { IContainer, IFood }
import from "result-ts-type" { Err, Ok, Result }

glob CreateFoodFormSchema = createFoodFormSchema.omit({"group": True, "container": True});

async def:pub createFood(inputs: CreateFoodInputs) -> Result[None, str] {
    validatedData = CreateFoodFormSchema.safeParse(inputs);
    if not validatedData.success {
        return Err("Validation failed");
    }
    newFood: dict[str, object] = {"name": validatedData.data.name, "quantity": (Number(validatedData.data.quantity) or None), "unit": (validatedData.data.unit or None), "expiry": (validatedData.data.expiry or None), "category": validatedData.data.category};
    result = await postFood(inputs.container, newFood);
    if result.ok {
        return Ok(None);
    }
    return Err(result.error);
}

async def:pub updateFood(inputs: UpdateFoodInputs) -> Result[None, str] {
    validatedData = createFoodFormSchema.safeParse(inputs);
    if not validatedData.success {
        return Err("Validation failed");
    }
    alteredFood: dict[str, object] = {"name": validatedData.data.name, "quantity": (Number(validatedData.data.quantity) or None), "unit": (validatedData.data.unit or None), "expiry": (validatedData.data.expiry or None), "category": validatedData.data.category};
    result = await putFood(inputs.container, inputs.id, alteredFood);
    if result.ok {
        return Ok(None);
    }
    return Err(result.error);
}

async def:pub removeFood(containerId: str, foodId: str) -> Result[None, str] {
    validatedData = deleteFoodFormSchema.safeParse({"foodId": foodId, "containerId": containerId});
    if not validatedData.success {
        return Err("Validation failed");
    }
    result = await deleteFood(containerId, foodId);
    if result.ok {
        return Ok(None);
    }
    return Err(result.error);
}

