import from urllib.parse { quote }

def:pub serializeOptions(options: dict[str, object]) -> str {
    parts: list[str] = [];
    for (key, value) in options.items() {
        parts.append(f"{quote(str(key), safe='')}={quote(str(value), safe='')}");
    }
