import from "@/env.mjs" { env }

glob VERCEL_API = "https://api.vercel.com";

def getHeaders() -> dict[str, str] {
    return {"Authorization": f"Bearer {env.VERCEL_TOKEN}", "Content-Type": "application/json"};
}

def getTeamParam() -> str {
    return (f"?teamId={env.VERCEL_TEAM_ID}" if env.VERCEL_TEAM_ID else "");
}

def isConfigured() -> bool {
    return not not (env.VERCEL_TOKEN and env.VERCEL_PROJECT_ID);
}

async def:pub getDomainConfig(domain: str) -> dict[str, object] | None {
    if not isConfigured() {
        return None;
    }
    res = await fetch(f"{VERCEL_API}/v6/domains/{domain}/config{getTeamParam()}", {"method": "GET", "headers": getHeaders()});
    if not res.ok {
        return None;
    }
    return await res.json() as dict[str, object];
}

async def:pub verifyDomain(domain: str) -> dict[str, object] | None {
    if not isConfigured() {
        return None;
    }
    res = await fetch(f"{VERCEL_API}/v9/projects/{env.VERCEL_PROJECT_ID}/domains/{domain}/verify{getTeamParam()}", {"method": "POST", "headers": getHeaders()});
    if not res.ok {
        return None;
    }
    return await res.json() as dict[str, object];
}

