def:pub saveWithToast(t: Callable[[str], str]) {
    store_snapshot = useResumeStore.getState();
    if not store_snapshot.dirty {
        return;
    }
    store_snapshot.save().then(lambda { toast.success(t("toolbar.saved")); }).catch(lambda { toast.error(t("common.saveError")); });
}

def:pub useSaveShortcut() {
    translation = useTranslation();
    t = translation.t;
    useEffect(lambda {
        def handler(e: KeyboardEvent) {
            if (e.metaKey or e.ctrlKey) and e.key == "s" {
                e.preventDefault();
                saveWithToast(t);
            }
        }
        window.addEventListener("keydown", handler);
        return lambda { window.removeEventListener("keydown", handler); };
    }, [t]);
    useEffect(lambda {
        def handler(e: Event) {
            if useResumeStore.getState().dirty {
                e.preventDefault();
            }
        }
        window.addEventListener("beforeunload", handler);
        return lambda { window.removeEventListener("beforeunload", handler); };
    }, []);
}

