# from: thangdevalone__modern-ui::lib/services/hooks/use-component-code.ts
async def axios_get(path: str, params: dict[str, str]) -> dict[str, str | None];

def:pub useComponentCode(componentName: str) -> dict[str, str | bool | None] {
    has code: str = "// Loading component code...";
    has is_loading: bool = True;
    has error: str | None = None;

    async can with [componentName] entry {
        is_loading = True;
        try {
            response = await axios_get("/api/component-code", {"name": componentName});
            response_code = response["code"] as str | None;
            if response_code {
                code = response_code;
                error = None;
            } else {
                code = "// Failed to load component code";
                response_error = response["error"] as str | None;
                error = response_error or "Unknown error";
            }
        } except Exception as e {
            print(f"Error fetching code for {componentName}: {str(e)}");
            code = "// Error loading component code";
            msg = str(e);
            error = msg if msg else "Failed to fetch component code";
        } finally {
            is_loading = False;
        }
    }

    return {"code": code, "isLoading": is_loading, "error": error};
}

