glob baseValue: dict[str, object] = {"profile": {"name": "Test User"}};

glob baseTheme: dict[str, str] = {"color": "#2f5785", "tagColor": "#2f5785"};

test "Resume returns nothing when value or theme is missing" {
    withoutValue = render(
        <IntlProvider locale="zh-CN" messages={zhCNMessages}>
            <Resume theme={baseTheme} />
        </IntlProvider>
    );
    assert withoutValue.container.firstChild is None;

    withoutTheme = render(
        <IntlProvider locale="zh-CN" messages={zhCNMessages}>
            <Resume value={baseValue} />
        </IntlProvider>
    );
    assert withoutTheme.container.firstChild is None;
}

test "Resume falls back to template1 when template is missing or unknown" {
    withoutTemplate = render(
        <IntlProvider locale="zh-CN" messages={zhCNMessages}>
            <Resume value={baseValue} theme={baseTheme} />
        </IntlProvider>
    );
    assert withoutTemplate.container.querySelector(".template1-resume") is not None;

    unknownTemplate = render(
        <IntlProvider locale="zh-CN" messages={zhCNMessages}>
            <Resume value={baseValue} theme={baseTheme} template="unknown-template" />
        </IntlProvider>
    );
    assert unknownTemplate.container.querySelector(".template1-resume") is not None;
}

