# from: travisjneuman__neumanos::utils/naturalLanguageParser.ts
import re;
import from "./dateUtils.jac" { formatDateKey }

def parsePriority(value: str) -> str | None {
    lower = value.lower();
    if lower in ["high", "urgent", "critical", "1"] {
        return "high";
    }
    if lower in ["medium", "med", "2"] {
        return "medium";
    }
    if lower in ["low", "3"] {
        return "low";
    }
    return None;
}

def parseDueDate(dateStr: str) -> str | None {
    lower = dateStr.lower().strip();
    if re.match(r"^\d{4}-\d{2}-\d{2}$", lower) {
        return lower;
    }
    today = Date();
    if lower == "today" {
        return formatDateKey(today) as str;
    }
    if lower == "tomorrow" {
        tomorrow = Date(today.getTime() + (24 * 60 * 60 * 1000));
        return formatDateKey(tomorrow) as str;
    }
    days = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
    if lower in days {
        dayIndex = days.index(lower);
        currentDay = today.getDay();
        daysAhead = dayIndex - currentDay;
        if daysAhead <= 0 {
            daysAhead = daysAhead + 7;
        }
        target = Date(today.getTime() + (daysAhead * 24 * 60 * 60 * 1000));
        return formatDateKey(target) as str;
    }
    return None;
}

def:pub parseTaskInput(input: str) -> dict[str, object] {
    text: str = input.strip();
    tags: list[str] = [];
    assignees: list[str] = [];
    priority: str | None = None;
    dueDate: str | None = None;
    project: str | None = None;
    for `match in re.finditer(r"#([a-zA-Z][a-zA-Z0-9-]*)", text) {
        tag: str = `match.group(1);
        if tag not in tags {
            tags = tags + [tag];
        }
        text = text.replace(`match.group(0), " ");
    }
    for `match in re.finditer(r"!([a-zA-Z0-9]+)", text) {
        priority = parsePriority(`match.group(1));
        text = text.replace(`match.group(0), " ");
    }
    for `match in re.finditer(r"@([a-zA-Z0-9_-]+)", text) {
        assignees = assignees + [`match.group(1)];
        text = text.replace(`match.group(0), " ");
    }
    for `match in re.finditer(r"\^([a-zA-Z0-9_-]+)", text) {
        project = `match.group(1);
        text = text.replace(`match.group(0), " ");
    }
    lowerText = text.lower();
    dueIdx = lowerText.find("due ");
    if dueIdx != -1 {
        rest = text[dueIdx + 4:].strip();
        duePart = rest.split()[0];
        dueDate = parseDueDate(duePart);
        text = (text[:dueIdx] + rest[len(duePart):]).strip();
    }
    title = re.sub(r"\s+", " ", text).strip();
    return {
        "title": title,
        "tags": tags,
        "priority": priority,
        "dueDate": dueDate,
        "assignees": assignees,
        "project": project,
    };
}

