# from: beyondlong__resume-builder::helpers/location.ts
import from "query-string" { default as qs }

def:pub getSearchObj() -> dict[str, object] {
    search = (window and window.location.search) or "";
    query = qs.parse(search);
    return query or {};
}

def:pub buildLocalizedPath(pathname: str, extraQuery: dict[str, object] | None = None) -> str {
    currentQuery = getSearchObj();
    merged = extraQuery if extraQuery else {};
    nextQuery = {**currentQuery, **merged};
    search = qs.stringify(nextQuery, {"skipEmptyString": True, "skipNull": True});
    return f"{pathname}?{search}" if search else pathname;
}

