glob endEvents: dict[str, str] = {"animation": "animationend", "OAnimation": "oAnimationEnd", "MozAnimation": "animationend", "WebkitAnimation": "webkitAnimationEnd"};

glob startEvents: dict[str, str] = {"animation": "animationstart", "OAnimation": "oAnimationStart", "MozAnimation": "animationStart", "WebkitAnimation": "webkitAnimationStart"};

def whichEvent(events: dict[str, str]) -> str | None {
    el = document.createElement("fakeelement");
    style = el["style"] as dict[str, object];
    for t in events {
        if t in style and style[t] is not None {
            return events[t];
        }
    }
    return None;
}

type EventFunction = Callable[[], str];

def:pub getStartEvent() -> str {
    return whichEvent(startEvents) or "";
}

def:pub getEndEvent() -> str {
    return whichEvent(endEvents) or "";
}

