# from: FullAgent__fulling::(landing)/_lib/get-github-star-count.ts
glob FALLBACK_STAR_COUNT: int = 2400;

glob GITHUB_REPOSITORY_API: str = "https://api.github.com/repos/FullAgent/fulling";

glob ONE_HOUR_IN_SECONDS: int = 60 * 60;

async def:pub getGitHubStarCount() -> int {
    try {
        response = await fetch(
            GITHUB_REPOSITORY_API,
            {"headers": {
                "Accept": "application/vnd.github+json",
                "User-Agent": "fulling-landing-page",
                "X-GitHub-Api-Version": "2022-11-28",
            }},
        );
        if not response.ok {
            return FALLBACK_STAR_COUNT;
        }
        repository = await response.json();
        stargazers_count = repository["stargazers_count"];
        if isinstance(stargazers_count, int) and stargazers_count >= 0 {
            return stargazers_count;
        }
        return FALLBACK_STAR_COUNT;
    } except Exception {
        return FALLBACK_STAR_COUNT;
    }
}

def:pub formatGitHubStarCount(starCount: int) -> str {
    if starCount >= 1_000_000 {
        scaled = starCount / 1_000_000;
        suffix = "M";
    } elif starCount >= 1_000 {
        scaled = starCount / 1_000;
        suffix = "K";
    } else {
        return str(starCount);
    }
    formatted = f"{scaled:.1f}";
    if formatted.endswith(".0") {
        formatted = formatted[:-2];
    }
    return formatted + suffix;
}

