glob SEQ: list[str] = ["ArrowUp", "ArrowUp", "ArrowDown", "ArrowDown", "ArrowLeft", "ArrowRight", "ArrowLeft", "ArrowRight", "b", "a"];

glob WORD = "joey";

def:pub KonamiListener() -> JsxElement {
    router = useRouter();

    useEffect(lambda {
        state = {"i": 0, "buf": ""};
        def onKey(e: KeyboardEvent) {
            expected = SEQ[state["i"]];
            got = (e.key.lower() if len(e.key) == 1 else e.key);
            if got == expected {
                state["i"] = state["i"] + 1;
                if state["i"] == len(SEQ) {
                    state["i"] = 0;
                    router.push("/secret");
                    return;
                }
            } else {
                state["i"] = (1 if got == SEQ[0] else 0);
            }
            if len(e.key) == 1 {
                state["buf"] = (state["buf"] + e.key.lower())[-len(WORD):];
                if state["buf"] == WORD {
                    state["buf"] = "";
                    router.push("/secret");
                }
            }
        };
        window.addEventListener("keydown", onKey);
        return lambda { window.removeEventListener("keydown", onKey); };
    }, [router]);

    <></>
}

