    has idleTimeoutRef: Ref[int | None] = Ref(None);

    def handle_change(e: ChangeEvent) {
        value = e.target.value;
        status = "saving";
        if typingTimeoutRef.current { clearTimeout(typingTimeoutRef.current); }
        if idleTimeoutRef.current { clearTimeout(idleTimeoutRef.current); }
        typingTimeoutRef.current = setTimeout(lambda {
            status = "saved";
            idleTimeoutRef.current = setTimeout(lambda { status = "idle"; }, 2000);
        }, 1000);
    }

    useEffect(lambda {
        return lambda {
            if typingTimeoutRef.current { clearTimeout(typingTimeoutRef.current); }
            if idleTimeoutRef.current { clearTimeout(idleTimeoutRef.current); }
        };
    }, []);

    <div className="flex flex-col gap-2">
        <InputGroup className="h-10 rounded-xl px-1">
            <InputGroupInput placeholder="Type message to save..." value={value} onChange={handle_change} />
            <InputGroupAddon align="inline-end" className="pr-3">
                {if status == "saving" {
                    <div className="flex items-center gap-1.5 text-xs text-muted-foreground font-medium">
