import from "react" { useEffect }

async def writeClipboardText(command: str) {
    if not navigator.clipboard.writeText {
        raise Exception("Clipboard API is unavailable.");
    }
    await navigator.clipboard.writeText(command);
}

def:pub CommandCopyButton(command: str, label: str, className: str | None = None) -> JsxElement {
    has status: str = "idle";

    useEffect(lambda {
        if status == "idle" {
            return lambda { };
        }
        timeout = setTimeout(lambda { status = "idle"; }, 2000);
        return lambda { clearTimeout(timeout); };
    }, [status]);

    async def handle_copy() {
        try {
            await writeClipboardText(command);
            status = "copied";
        } except Exception {
            status = "failed";
        }
    }

    icon = <Copy className="h-4 w-4" aria-hidden="true" />;
    if status == "copied" {
        icon = <Check className="h-4 w-4" aria-hidden="true" />;
    }

    return <div className={cn("flex items-center gap-2", className)}><Button type="button" variant="outline" size="icon" onClick={handle_copy} aria-label={f"Copy {label}"}>{icon}</Button></div>;
}

