    has bg: str;
    has time: str;
}

def formatTimeRange(start: Date, end: Date) -> str {
    if start.toDateString() == end.toDateString() {
        startTime = start.toLocaleTimeString("en-US", {"hour": "numeric", "minute": "2-digit", "hour12": True});
        endTime = end.toLocaleTimeString("en-US", {"hour": "numeric", "minute": "2-digit", "hour12": True});
        return f"{startTime} – {endTime}";
    }
    startLabel = start.toLocaleDateString("en-US", {"month": "short", "day": "numeric"});
    endLabel = end.toLocaleDateString("en-US", {"month": "short", "day": "numeric"});
    return f"{startLabel} – {endLabel}";
}

