type FollowUpDepth = "LIGHT" | "MODERATE" | "DEEP";

glob:pub DEFAULT_FOLLOW_UP_DEPTH: FollowUpDepth = "MODERATE";

glob MAX_FOLLOW_UPS: dict[str, int] = {"LIGHT": 0, "MODERATE": 2, "DEEP": 5};

glob MAX_FOLLOW_UPS_RESEARCH: dict[str, int] = {"LIGHT": 2, "MODERATE": 4, "DEEP": 8};

def:pub normalizeFollowUpDepth(value: str | None) -> FollowUpDepth {
    if not value {
        return DEFAULT_FOLLOW_UP_DEPTH;
    }
    normalized = value.strip().upper();
    if normalized == "LIGHT" or normalized == "MODERATE" or normalized == "DEEP" {
        return normalized as FollowUpDepth;
    }
    return DEFAULT_FOLLOW_UP_DEPTH;
}

def:pub maxFollowUpsForDepth(depth: str | None, questionType: str | None = None) -> int {
    normalized = normalizeFollowUpDepth(depth);
    if questionType == "RESEARCH" {
        return MAX_FOLLOW_UPS_RESEARCH[normalized];
    }
    return MAX_FOLLOW_UPS[normalized];
}

