async def requireAdmin() -> object {
    session = await auth.api.getSession({"headers": await headers()});
    if (session is None) {
        raise ValueError("Unauthorized");
    }
    if (session.user.role != "admin") {
        raise ValueError("Unauthorized");
    }
    return session;
}

async def:pub getNewsletterStats() -> dict[str, int] {
    await requireAdmin();
    subscribers = await db.select({"id": user.id}).from(user).where(`and(eq(user.newsletterSubscribed, true), isNotNull(user.newsletterId)));
    return {"subscriberCount": len(subscribers)};
}

