import from "@/lib/prep/answer-audio" { prepAnswerAudioStoragePath }
import from "@/lib/storage-signed-url" { resolveStorageSignedUrl }
import from "@/lib/supabase/admin" { supabaseAdmin }
import base64;

glob:pub PREP_ANSWER_AUDIO_BUCKET = "recordings";

async def:pub uploadPrepAnswerAudio(sessionId: str, attemptId: str, audio: dict[str, str]) -> str | None {
    storagePath = prepAnswerAudioStoragePath(sessionId, attemptId, audio["mimeType"]);
    buffer = base64.b64decode(audio["base64"]);
    contentType = audio["mimeType"].strip();
    if not contentType {
        if storagePath.endswith(".m4a") {
            contentType = "audio/mp4";
        } else {
            contentType = "audio/webm";
        }
    }
    uploadResponse = await supabaseAdmin.storage.from(PREP_ANSWER_AUDIO_BUCKET).upload(storagePath, buffer, {"contentType": contentType, "upsert": True});
    if uploadResponse.error {
        return None;
    }
    return storagePath;
}

async def:pub resolvePrepAnswerAudioUrl(storedPath: str | None) -> str | None {
    if not storedPath or not storedPath.strip() {
        return None;
    }
    return await resolveStorageSignedUrl(PREP_ANSWER_AUDIO_BUCKET, storedPath.strip());
}

