async def search(_: str, term: str, page: float) -> list[Note] {
    url = format({"pathname": "/api/search", "query": {"term": term, "page": page}});
    res = await fetch(url, {"headers": {"Content-Type": "application/json"}});
    return (await res.json()) as list[Note];
}

def:pub useSearch(value: str, page: float = 1, debounce: float = 300) -> dict[str, object] {
    (term, set_term) = useState("");
    useEffect(lambda {
        timer = setTimeout(lambda { set_term(value); }, debounce);
        return lambda { clearTimeout(timer); };
    }, [value, debounce]);
    return useSWR(lambda { term ? ["search", term, page] : None; }, search);
}

