obj DropdownOption {
    has value: str | int;
    has label: str;
    has disabled: bool = False;
}

def handle_calendar_change(value: str | int, handler: Callable[[ChangeEvent], None]) {
    event = {"target": {"value": str(value)}} as ChangeEvent;
    handler(event);
}

def CalendarDropdown(dropdownProps: DropdownProps) -> JsxElement {
    selectedLabel = "";
    options = dropdownProps.options as list[DropdownOption] | None;
    if options {
        for option in options {
            if option.value == dropdownProps.value {
                selectedLabel = option.label;
                break;
            }
        }
    }
    <Select
        onValueChange={lambda (value: str) {
            if dropdownProps.onChange and value is not None {
                handle_calendar_change(value, dropdownProps.onChange);
            }
        }}
        value={str(dropdownProps.value)}
    >
        <SelectTrigger className="first:grow">
            <SelectValue>{selectedLabel}</SelectValue>
        </SelectTrigger>
        <SelectContent align="start">
            {if options {
                for option in options {
                    <SelectItem disabled={option.disabled} key={str(option.value)} value={str(option.value)}>
                        {option.label}
                    </SelectItem>
                }
            }}
        </SelectContent>
    </Select>
}

