def:pub CalendarNotificationsSection(
    notificationPermission: str,
    requestingPermission: bool,
    onRequestPermission: Callable[[], None],
) -> JsxElement {
    statusText = (
        "✅ Notifications are enabled"
        if notificationPermission == "granted"
        else ("❌ Notifications are blocked" if notificationPermission == "denied" else "⏸️ Not yet requested")
    );
    badgeText = (
        "Enabled"
        if notificationPermission == "granted"
        else ("Blocked" if notificationPermission == "denied" else "Not Set")
    );
    badgeClass = (
        "bg-status-success/10 text-status-success"
        if notificationPermission == "granted"
        else (
            "bg-status-error/10 text-status-error"
            if notificationPermission == "denied"
            else "bg-status-warning/10 text-status-warning"
        )
    );
    return (
        <div className="bento-card p-6">
            <h2 className="text-lg font-semibold text-text-light-primary dark:text-text-dark-primary mb-4">
                🔔 Calendar Notifications
            </h2>
            <p className="text-sm text-text-light-secondary dark:text-text-dark-secondary mb-6">
                Enable browser notifications for event reminders.
            </p>
            <div className="mb-4 p-4 bg-surface-light-elevated dark:bg-surface-dark-elevated rounded-lg">
                <div className="flex items-center justify-between">
                    <div>
                        <p className="text-sm font-medium text-text-light-primary dark:text-text-dark-primary">
                            Notification Status
                        </p>
                        <p className="text-xs text-text-light-secondary dark:text-text-dark-secondary mt-1">
                            {statusText}
                        </p>
                    </div>
                    <span className={f"px-3 py-1 text-xs font-medium rounded-full {badgeClass}"}>
                        {badgeText}
                    </span>
                </div>
            </div>
            {notificationPermission != "granted" and (
                <button
                    onClick={onRequestPermission}
                    disabled={(requestingPermission or (notificationPermission == "denied"))}
                    className="w-full px-4 py-3 bg-accent-primary hover:bg-accent-primary-hover disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-lg font-medium shadow-soft hover:shadow-medium transition-all duration-200"
                >
                    {"⏳ Requesting..." if requestingPermission else "🔔 Enable Notifications"}
                </button>
            )}
        </div>
    );
}

