# from: vanxh__openbio::hooks/use-debounce.ts
import from "react" { useEffect, useState }

def:pub useDebounce[T](value: T, delay: float | None = None) -> T {
    state = useState(value);
    debouncedValue = state[0];
    setDebouncedValue = state[1];
    useEffect(lambda {
        resolved = delay if delay is not None else 500.0;
        timer = setTimeout(lambda { setDebouncedValue(value); }, resolved);
        return lambda { clearTimeout(timer); };
    }, [value, delay]);
    return debouncedValue;
