import from "react" { useEffect, useRef }

def:pub ViewTracker(postId: str) -> None {
    hasTrackedInitial = useRef(False);
    intervalRef = useRef(None);

    async def track_view() -> None {
        try {
            await fetch("/api/blog/track-view", {"method": "POST", "headers": {"Content-Type": "application/json"}, "body": JSON.stringify({"postId": postId})});
        } except Exception as error {
            console.error("Failed to track view:", error);
        }
    }

    useEffect(lambda () -> object {
        if not hasTrackedInitial.current {
            track_view();
            hasTrackedInitial.current = True;
        }
        intervalRef.current = setInterval(lambda { track_view(); }, 60000);
        return lambda {
            if intervalRef.current {
                clearInterval(intervalRef.current);
            }
        };
    }, [postId]);

    return None;
}

