        if me.mode == "session" {
            return {"action": "endSessionThenRedirect", "to": "/login"};
        }
        return {"action": "redirect", "to": "/"};
    }
    if result.status == 401 {
        return {"action": "redirect", "to": "/login"};
    }
    return {"action": "rethrow", "error": result.error};
}

