import from "crypto" { createHmac }
import from "meilisearch" { default as MeiliSearch }
import from "@/env" { env }

def:pub getOpenGraphImageUrl(slug: str) -> str {
    hmac = createHmac("sha256", env.OG_HMAC_SECRET);
    hmac.update(JSON.stringify({"slug": slug}));
