def palette_action_icon(name: str | None) -> JsxElement | None {
    if name == "settings" { return <SettingsIcon />; }
    if name == "file-plus" { return <FilePlusIcon />; }
    if name == "terminal" { return <TerminalIcon />; }
    if name == "wand" { return <WandSparklesIcon />; }
