def:pub CommandPaletteDemo(
    button_label: str = "Command Palette",
    placeholder: str = "Type a command or search...",
    empty_message: str = "No results found.",
    actions_heading: str = "Actions",
    files_heading: str = "Files",
    actions: list[CommandPaletteAction] = default_actions,
    files: list[CommandPaletteFile] = default_files,
) -> JsxElement {
    has open: bool = False;

    def handle_open_change(next_open: bool) {
        open = next_open;
    }

    def open_dialog(e: MouseEvent) {
        open = True;
    }

    <div className="flex flex-col gap-4">
        <Button onClick={open_dialog} variant="outline" className="w-fit cursor-pointer">
            {button_label}
        </Button>
        <CommandDialog open={open} onOpenChange={handle_open_change}>
            <Command>
                <CommandInput placeholder={placeholder} />
                <CommandList>
                    <CommandEmpty>{empty_message}</CommandEmpty>
                    <CommandGroup heading={actions_heading}>
                        {for action in actions {
                            def handle_action_select(current_value: str) {
                                if action.on_select {
                                    action.on_select();
                                }
                            }
                            <CommandItem
                                key={action.label}
                                className="cursor-pointer"
                                onSelect={handle_action_select}
                            >
                                {palette_action_icon(action.icon_name)}
                                <span>{action.label}</span>
                                {if action.shortcut {
                                    <CommandShortcut>{action.shortcut}</CommandShortcut>
                                }}
                            </CommandItem>
                        }}
                    </CommandGroup>
                    <CommandSeparator />
                    <CommandGroup heading={files_heading}>
                        {for file in files {
                            def handle_file_select(current_value: str) {
                                if file.on_select {
                                    file.on_select();
                                }
                            }
                            <CommandItem
                                key={file.path}
                                className="cursor-pointer gap-2.5"
                                onSelect={handle_file_select}
                            >
                                <FileIcon className="size-4 shrink-0" />
                                <div className="flex flex-1 items-center gap-2">
                                    <span className="font-medium">{file.name}</span>
                                    <span className="text-muted-foreground text-sm">{file.path}</span>
                                </div>
                            </CommandItem>
                        }}
                    </CommandGroup>
                </CommandList>
            </Command>
        </CommandDialog>
    </div>
}

