def parse_qs(qs: str) -> dict[str, str] {
    out: dict[str, str] = {};
    if not qs {
        return out;
    }
    for part in qs.split("&") {
        if "=" in part {
            (k, v) = part.split("=", 1);
            out[k] = v;
        }
    }
    return out;
}

def encode_qs(params: dict[str, str]) -> str {
    return "&".join([f"{k}={v}" for (k, v) in params.items()]);
}

import from "react" { useEffect }
import from "next/navigation" { usePathname, useRouter, useSearchParams }
import from "@/components/ui/input" { Input }
import from "lucide-react" { SearchIcon }

def:pub PreviewListSearch() -> JsxElement {
    search_params = useSearchParams();
    query = search_params.get("q") or "";
    has value: str = query;
    has debounced_query: str = query;
    pathname = usePathname();
    search_params_string = str(search_params);
    router = useRouter();

    useEffect(lambda {
        timer = setTimeout(lambda { debounced_query = value; }, 300);
        return lambda { clearTimeout(timer); };
    }, [value]);

    def handle_change(e: ChangeEvent) {
        value = e.target.value;
    }

    def handle_search() {
        if not search_params_string and not debounced_query {
            return;
        }
        params = parse_qs(search_params_string);
        if not debounced_query {
            filtered = {k: v for (k, v) in params.items() if k != "q"};
            qs = encode_qs(filtered);
            router.push(f"{pathname}?{qs}" if qs else pathname);
            return;
        }
        params["q"] = debounced_query;
        router.push(f"{pathname}?{encode_qs(params)}");
    }

    useEffect(lambda { handle_search(); }, [debounced_query]);
    useEffect(lambda { value = query; }, [query]);

    <div className="relative">
        <Input
            className="ps-9 max-w-60 w-full bg-background"
            placeholder="Search"
            value={value}
            onChange={handle_change}
        />
        <SearchIcon className="h-5 w-5 absolute start-2 inset-y-0 my-auto text-muted-foreground" />
    </div>
}

