# from: ppxb__jm-boom::features/settings/api-endpoint-section.tsx
import from "lucide-react" { CheckCircle2Icon, LoaderCircleIcon, NetworkIcon, RefreshCwIcon, XCircleIcon }
import from "@/components/ui/button" { Button }
import from "@/components/ui/select" { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue }
import from "@/lib/utils" { cn }
import from "./shared.jac" { SettingRow, SettingsSection }
import from "./use-endpoint-options.jac" { formatEndpoint }

obj ApiEndpointProbe {
    has endpoint: str,
        ok: bool = False,
        latencyMs: float = 0.0;
}

def latencyTone(latencyMs: float) -> str {
    if latencyMs <= 500 {
        return "text-emerald-600 dark:text-emerald-400";
    }
    if latencyMs <= 1500 {
        return "text-amber-600 dark:text-amber-400";
    }
    return "text-orange-600 dark:text-orange-400";
}

def EndpointDisplay(
    endpoint: str,
    probe: ApiEndpointProbe | None = None,
    isDiscovering: bool = False,
    isRefreshingEndpoints: bool = False,
    compact: bool = False
) -> JsxElement {
    if isDiscovering or isRefreshingEndpoints {
        return <LoaderCircleIcon className="size-4 animate-spin" />;
    }
    if probe is None {
        return <span>{formatEndpoint(endpoint)}</span>;
    }
    if probe.ok {
        return <span className={cn("inline-flex items-center gap-1", latencyTone(probe.latencyMs))}>
            <CheckCircle2Icon className="size-4" />
            {formatEndpoint(endpoint)}
            {not compact and <span>{f"{int(probe.latencyMs)} ms"}</span>}
        </span>;
    }
    return <span className="inline-flex items-center gap-1">
        <XCircleIcon className="size-4" />
        {formatEndpoint(endpoint)}
    </span>;
}

def:pub ApiEndpointSection(
    endpoint: str,
    endpointOptions: list[ApiEndpointProbe],
    isDiscovering: bool,
    isRefreshingEndpoints: bool,
    onEndpointChange: Callable[[str], None],
    onRefresh: Callable[[], None]
) -> JsxElement {
    probe = None;
    for option in endpointOptions {
        if option.endpoint == endpoint {
            probe = option;
            break;
        }
    }
    def handle_refresh() {
        onRefresh();
    }
    return <SettingsSection icon={<NetworkIcon className="size-4" />} title="网络">
        <SettingRow title="API 接口" description="测速后自动优选延迟最低的可用接口">
            <div className="flex items-center gap-2">
                <Select value={endpoint} onValueChange={onEndpointChange}>
                    <SelectTrigger>
                        <SelectValue>
                            <EndpointDisplay
                                endpoint={endpoint}
                                probe={probe}
                                isDiscovering={isDiscovering}
                                isRefreshingEndpoints={isRefreshingEndpoints}
                                compact={True}
                            />
                        </SelectValue>
                    </SelectTrigger>
                    <SelectContent>
                        <SelectGroup>
                            {for option in endpointOptions {
                                <SelectItem key={option.endpoint} value={option.endpoint}>
                                    <EndpointDisplay
                                        endpoint={option.endpoint}
                                        probe={option}
                                        isDiscovering={isDiscovering}
                                        isRefreshingEndpoints={isRefreshingEndpoints}
                                    />
                                </SelectItem>
                            }}
                        </SelectGroup>
                    </SelectContent>
                </Select>
                <Button variant="outline" size="icon" onClick={handle_refresh} disabled={isRefreshingEndpoints}>
                    <RefreshCwIcon className={cn("size-4", isRefreshingEndpoints and "animate-spin")} />
                </Button>
            </div>
        </SettingRow>
    </SettingsSection>;
}

