import from "react" { useEffect }
import from "@/components/ui/button" { Button }
import from "@/lib/utils" { cn }
import from "lucide-react" { Copy, Check }

glob CODE: str = "SHADCN-PRO";
glob DURATION: int = 3500;

def:pub ButtonDemo() -> JsxElement {
    has copied: bool = False;
    has show_confirmation: bool = False;
    has progress: float = 0.0;

    useEffect(lambda {
        if not copied {
            return lambda { };
        }
        show_timer = setTimeout(lambda { show_confirmation = True; }, 300);
        start_time = Date.now();
        interval = setInterval(lambda {
            elapsed = Date.now() - start_time;
            new_progress = min((elapsed / DURATION) * 100, 100);
            progress = new_progress;
            if elapsed >= DURATION {
                clearInterval(interval);
                show_confirmation = False;
                setTimeout(lambda {
                    copied = False;
                    progress = 0.0;
                }, 300);
            }
        }, 16);
        return lambda {
            clearInterval(interval);
            clearTimeout(show_timer);
        };
    }, [copied]);

    async def handle_copy(e: MouseEvent) {
        await navigator.clipboard.writeText(CODE);
        copied = True;
    }

    <div className="relative overflow-hidden flex items-center justify-center bg-muted rounded-full px-6 min-w-64 h-12 border border-border">
        <div
            className={cn(
                "absolute left-0 top-0 bottom-0 bg-primary/15 transition-opacity duration-500 ease-in-out",
                "opacity-100" if copied else "opacity-0"
            )}
            style={{"width": f"{progress}%"}}
        />
        <div
            className={cn(
                "absolute inset-0 flex items-center justify-between pl-6 pr-2 transition-all duration-500 ease-in-out",
                "opacity-0 blur-md scale-95 pointer-events-none z-0" if copied else "opacity-100 blur-none scale-100 pointer-events-auto z-20"
            )}
        >
            <span className="text-sm font-mono font-medium tracking-widest text-muted-foreground select-all truncate max-w-36">
                {CODE}
            </span>
            <Button
                onClick={handle_copy}
                className="gap-1.5 rounded-full cursor-pointer select-none hover:bg-primary/80"
            >
                <Copy className="w-3.5 h-3.5" />
                Copy
            </Button>
        </div>
        <div
            className={cn(
                "relative flex items-center gap-2 transition-all duration-700 ease-in-out pointer-events-none z-10",
                "opacity-100 blur-none scale-100" if show_confirmation else "opacity-0 blur-md scale-105"
            )}
        >
            <div className="w-6 h-6 bg-primary rounded-full flex items-center justify-center">
                <Check
                    className="w-3.5 h-3.5 text-primary-foreground"
                    style={{
                        "strokeDasharray": 24,
                        "strokeDashoffset": 0 if show_confirmation else 24,
                        "transition": "stroke-dashoffset 0.6s ease-in-out 0.3s",
                    }}
                />
            </div>
            <span className="text-sm font-semibold text-foreground">
                Copied to clipboard!
            </span>
        </div>
    </div>
}

