def:pub handleFieldValue(fieldKey: str, fieldValue: object, fieldOptions: GenericFieldOptions | None = None) -> GenericFieldOptions {
    defaultOptions = setDefaultOptions(fieldKey, fieldValue);
    mergedOptions = fieldOptions if fieldOptions is not None else {};
    options = {**defaultOptions, **mergedOptions};
    baseType = unwrapZodType(fieldValue);
    if isZodString(baseType) {
        return handleZodString(options);
    }
    elif isZodNumber(baseType) {
        return handleZodNumber(options);
    }
    elif isZodBoolean(baseType) {
        return handleZodBoolean(options);
    }
    elif isZodEnum(baseType) {
        return handleZodEnum(options, fieldValue);
    }
    elif isZodNativeEnum(baseType) {
        return handleNativeZodEnum(options, fieldValue);
    }
    else {
        raise ValueError("Unsupported Zod type");
    }
}

