import from "@/components/ui/progress" { Progress }
import from "@/components/ui/button" { Button }

glob TOTAL_STEPS: int = 4;

def:pub OnboardingStepper() -> JsxElement {
    has current: int = 1;
    progressPct: float = ((current - 1) / (TOTAL_STEPS - 1)) * 100;

    def handle_back(e: MouseEvent) {
        current = max(1, current - 1);
    }

    def handle_next(e: MouseEvent) {
        current = min(TOTAL_STEPS, current + 1);
    }

    <div className="w-full max-w-md rounded-xl border bg-background p-6 space-y-6">
        <div className="space-y-2">
            <div className="flex items-center justify-between text-xs text-muted-foreground">
                <span>Step {current} of {TOTAL_STEPS}</span>
                <span>{round(progressPct)}% complete</span>
            </div>
            <Progress
                value={progressPct}
                className="**:data-[slot='progress-track']:h-1.5!"
            />
        </div>
        <div className="flex justify-between">
            <Button
                variant="outline"
                size="sm"
                className="cursor-pointer"
                onClick={handle_back}
                disabled={current == 1}
            >
                Back
            </Button>
            <Button
                size="sm"
                className="cursor-pointer hover:bg-primary/80"
                onClick={handle_next}
                disabled={current == TOTAL_STEPS}
            >
                {"Finish" if current == TOTAL_STEPS - 1 else "Next"}
            </Button>
        </div>
    </div>
}

