# from: shadcnspace__shadcnspace::hooks/use-block-theme.tsx
import from "react" { useRef, useState }

type Theme = str;

type BlockThemeValue = {
    theme: Theme,
    setTheme: Callable[[Theme], None],
    iframeRef: object,
};

def:pub useBlockTheme() -> BlockThemeValue {
    themeState = useState("light");
    theme = themeState[0];
    setThemeState = themeState[1];
    iframeRef = useRef(None);

    def handleThemeChange(newTheme: Theme) {
        setThemeState(newTheme);
        iframe = iframeRef.current;
        if iframe and iframe.contentDocument and iframe.contentDocument.documentElement {
            iframeDocument = iframe.contentDocument.documentElement;
            if newTheme == "dark" {
                iframeDocument.classList.remove("light");
                iframeDocument.classList.add("dark");
            }
            if newTheme == "light" {
                iframeDocument.classList.remove("dark");
                iframeDocument.classList.add("light");
            }
        }
    }

    return {
        "theme": theme,
        "setTheme": handleThemeChange,
        "iframeRef": iframeRef,
    };
}

